WITH payload AS (SELECT $archive_payload$[{"id":"61ea66e3-7e16-5a1c-ac07-e48ccb87b735","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -وكالة بأجرة -دعوى أتعاب تعقيب -إنكار املدعى عليه قدر العوض -إحضار البينة على إمتام العمل -نكول املدعى عليه عن اليمن -بذل املدعي لليمن -احلكم على املدعى عليه بدفع أتعاب التعقيب.","document_number":"34183132","case_number":"3256388","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض و املكلف بعمل فضيلة الشيخ د","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/9","year":"1434","subject":"أتعاب -وكالة بأجرة -دعوى أتعاب تعقيب -إنكار املدعى عليه قدر العوض -إحضار البينة على إمتام العمل -نكول املدعى عليه عن اليمن -بذل املدعي لليمن -احلكم على املدعى عليه بدفع أتعاب التعقيب.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34183132 :‬تاريخه‪1434/4/9 :‬هـ‬\n                    ‫رقم الدعوى‪3256388 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34235690‬تاريخه‪1434/6/10 :‬هـ‬\n\n\n‫أتعــاب ‪ -‬وكالــة بأجــرة ‪ -‬دعــوى أتعــاب تعقيــب ‪ -‬إنــكار املدعــى عليــه‬\n‫قــدر العــوض ‪ -‬إحضــار البينــة علــى إمتــام العمــل ‪ -‬نكــول املدعــى عليــه‬\n‫عــن اليمــن ‪ -‬بــذل املدعــي لليمــن ‪ -‬احلكــم علــى املدعــى عليــه بدفــع‬\n                                                             ‫أتعــاب التعقيــب‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم «البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                              ‫أنكر»‪.‬‬\n‫‪ -2‬قــال ابــن القيــم يف الطــرق احلكمية(قــال شــيخ اإلســام ابــن تيميــة‬\n‫رحمــه اهلل ورضــي اهلل عنــه وليــس املنقــول عــن الصحابــة رضــي اهلل‬\n‫عنهــم بالنكــول ورد اليمــن مبختلــف بــل هــذا لــه موضــع وهــذا لــه‬\n‫موضــع فــكل موضــع أمكــن املدعــي معرفتــه والعلــم بــه رد املدعــى عليــه‬\n‫اليمــن فإنــه إن حلــف‪-‬أي املدعــي‪ -‬اســتحق وإن لــم يحلــف لــم يحكــم‬\n‫لــه بنكــول املدعــى عليــه وهــذا كحكومــة عثمــان واملقــداد فــإن املقــداد‬\n‫قــال لعثمــان احلــف أن الــذي دفعتــه إلــي كان ســبعة آالف وخذهــا فــإن‬\n‫املدعــي هنــا ميكنــه معرفــة ذلــك والعلــم بــه كيــف وقــد ادعــى بــه فــإذا‬\n                               ‫لــم يحلــف لــم يحكــم لــه إال ببينــة أو إقــرار) ‪.‬‬\n\n\n\n\n                                                                                        ‫‪40‬‬\n\f     ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليهــا بأنــه أبــرم معهــا عقــد وكالــة‬\n     ‫بأجــرة يف التعقيــب علــى أحــد املعامــات لــدى اجلهــات احلكوميــة حلــن‬\n     ‫إنهائهــا مقابــل مبلــغ مقطــوع ذكــر قــدره وألنــه قــام بالعمــل املطلــوب‬\n     ‫ولــم يســلم شــيئا فيطلــب إلزامهــا بدفــع كامــل املبلــغ ‪ -‬أقــر وكيــل‬\n     ‫املدعــى عليهــا بالوكالــة للتعقيــب لــدى اجلهــات احلكوميــة وأنــه قــام‬\n     ‫ببعــض العمــل وأنكــر قــدر العــوض ‪ -‬بســؤال املدعــي عــن دعــواه قــرر‬\n     ‫بــأال بينــة لديــه ويطلــب ميــن املدعــى عليهــا ‪ -‬ردت اليمــن علــى املدعــي‬\n     ‫فحلــف علــى صحــة مــا ورد يف دعــواه ‪ -‬وجلميــع مــا تقــدم فقــد ألــزم‬\n     ‫القاضــي املدعــى عليهــا بــأن تدفــع للمدعــي مبلغــا ذكــر قــدره وهــذا‬\n     ‫احلكــم حضــوري يف حــق املدعــى عليهــا إســتناد َا علــى الفقــرة األولــى‬\n     ‫مــن الالئحــة التنفيذيــة للمــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n                        ‫الشــرعية ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪41‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...................‬املــازم القضائــي يف‬\n‫احملكمــة العامــة بالريــاض و املكلــف بعمــل فضيلــة الشــيخ‬\n‫د‪ ...........................‬أثنــاء إجازتــه وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪ 3256388‬وتاريــخ‬\n‫‪1432/02/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32174878‬وتاريــخ‬\n‫‪1432/02/26‬ه ـ ففــي يــوم األربعــاء املوافــق ‪ 1432/10/23‬حضــر‬\n‫‪ ................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..............‬‬\n‫كمــا حضــر حلضــوره ‪.................‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ‪ ...............‬بالوكالــة الصــادرة‬‫املدنــي رقــم ‪ .............‬بصفتــه وكيـ ً‬\n‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 41712‬وتاريــخ‬\n‫‪ 1432/05/09‬ه ـ املجعــول لــه فيهــا حق املداعــاة و املخاصمة و املصاحلة‬\n‫ا لقــد اتفقــت مــع املدعــى‬  ‫و قبــول األحــكام ونقيهــا وادعــى األول قائ ـ ً‬\n‫عليهــا علــى أن أقــوم بتنظيــم زوائــد األرض اململوكــة بالصــك رقــم‬\n‫‪ 1/52‬يف ‪1396/6/4‬ه ـ و الواقعــة علــى طريــق ‪ ....‬الزوائــد التــي بينهــا‬\n‫وبــن طريــق امللــك عبــد اهلل وذلــك مقابــل أجــرة أتعــاب وقدرهــا ثالثــة‬\n‫ماليــن ريــال ولــم أســتلم شــيئ ًا مــن املبلــغ حتــى اآلن أطلــب إلــزام املدعــى‬\n‫عليهــا بتســليمي املبلــغ املدعــى بــه وقــدره ثالثــة ماليــن ريــال هــذه دعواي‬\n‫وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي قال ما ذكــره املدعي‬\n‫مــن أنــه اتفــق مــع موكلتــي علــى أن يقــوم بتنظيــم زوائــد األرض‬\n‫املذكــورة بالدعــوى فهــذا صحيــح و أمــا مــا ذكــره مــن أن االتفــاق‬\n‫كان علــى ثالثــة ماليــن فغيــر صحيــح و الصحيــح أن موكلتــي اتفقــت‬\n\n                                                                                              ‫‪42‬‬\n\f     ‫مــع املدعــي علــى أجــرة غيــر مقــدرة وقالــت موكلتي للمدعي ســأعطيك‬\n     ‫مــا يقدرنــي اهلل عليــه وقــد اســتلم املدعــي مــن موكلتــي مائــة وســبعة‬\n     ‫وثالثــن ألــف ريــال علــى دفعــات وذلــك مقابــل أتعابــه هــذه إجابتــي‬\n     ‫وبســؤال املدعــي البينــة علــى دعــواه قــال ليــس لــدي بينــة و أطلــب ميــن‬\n     ‫املدعــى عليهــا هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n     ‫قــال لــدي شــهود علــى مــا ذكرتــه ونفــي مــا ذكــر املدعــي وعليــه رفعــت‬\n     ‫اجللســة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......................‬املالزم القضائي‬\n     ‫لدى فضيلة الشــيخ د‪ .................‬ففي يوم الســبت املوافق ‪1433/1/29‬‬\n     ‫ه ـ حضــر‪ ......................‬ســعودي بالســجل ‪ ................‬وحضــر وكيلــه‬\n     ‫‪ ..................‬ســعودي بالســجل ‪ ..................‬بالوكالــة رقــم ‪ 8738‬تاريــخ‬\n     ‫‪1432/2/1‬ه ـ جلــد ‪ 4538‬والصــادرة مــن كتابــة العــدل الثانيــة بجنــوب‬\n     ‫الريــاض وحضــر حلضــوره ‪......................‬ســعودي بالســجل ‪..............‬‬\n     ‫وكيــا عــن ‪ .....................‬ســعودية بالســجل ‪ .................‬بالوكالــة رقــم‬\n     ‫‪ 41712‬تاريــخ ‪1432/5/9‬ه ـ الصــادرة مــن كتابــة عــدل شــمال جــدة و‬\n     ‫ا ينــوب عنــي يف‬     ‫املتضمــن قولهــا إننــي …………………وكي ـ ً‬\n     ‫مراجعــة الدعــوى املقامــة مــن ‪ ...................‬و لــه حــق املداعاة و املخاصمة‬\n     ‫و املصاحلــة وقبــول احلكــم ونفيــه الــخ وادعــى عليــه قائــا لقــد اتفقــت مــع‬\n     ‫موكلــت هــذا احلاضــر اتفاقــا شــفهيا علــى أن أقــوم بعمل تنظيم شــواطر‬\n     ‫األرض احلكوميــة وإضافتهــا إلــى أرضهــا مقابــل أتعــاب ثالثــة ماليــن‬\n     ‫ريــال وبعــد انتهــاء العمــل املتفــق عليــه لــم تعطينــي حقــي وأنــا أطلــب أن‬\n     ‫تعطينــي حقــي هــذه دعــواي وبعــرض الدعــوى علــى املدعــي عليــه وكالــة‬\n     ‫أجــاب بقولــه أن مــا يدعيــه املدعــي مــن االتفاقيــة صحيــح أمــا أتعــاب‬\n     ‫العمــل فلــم يتفــق عليــه املدعــي مــع موكلتــي وقالــت له ســأقوم بإعطائك‬\n\n\n‫‪43‬‬\n\f‫مــا يقدرنــي اهلل عليــه وبعــد ذلــك قــام املدعــي ببعــض العمــل و بعــد طلبــه‬\n‫ثالثــة ماليــن إلعطائهــا مهندســن يف البلديــة رفضــت موكلتــي هــذا‬\n‫األمــر وســحبت الوكالــة منــه ووكلــت شــخص آخــر هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــي قــال بــل الصحيــح مــا ذكرتــه وبعــد انتهــاء‬\n‫دوري يف املعاملــة وحتولــت إلــى كتابــة العــدل لإلفــراغ كانــت وكالتــي‬\n‫غيــر مخولــة لــي باإلفــراغ فقامــت ‪ .........‬بإعطائــي وكالــة جديــدة‬\n‫تخولنــي اإلفــراغ ثــم قامــت بعمــل وكالــة أخــرى ‪ ......................‬وعنــد‬\n‫مراجعتــي لكتابــة العــدل لإلفــراغ وإضافــة الزوائــد التنظيميــة حضــر‬\n‫شــخص يف كتابــة العــدل يقــول أن ‪ .............‬اصــدرة وكالة ل‪................‬‬\n‫وأنــه هــو املخــول باإلفــراغ ثــم بعــد ذلــك قــام ‪ ......‬بعمــل وكالــة لــي وبعــد‬\n‫ذلــك حضــر ‪ ...........‬أو شــخص آخــر بإفــراغ صــك بعــد انتهــاء املعاملــة‬\n‫كاملــة وصــدور صــك ملكيــة ل‪ .........‬بكامــل املســاحات والزوائــد‬\n‫وأنــا أطلــب حضــور ‪ .........‬شــخصيا وحتلــف وأقبــل ميينهــا علــى أن أتعابــي‬\n‫ليســت ثالثــة ماليــن وأنهــا قالــت أعطيــك الــذي يقدرنــي اهلل عليــه‬\n‫هكــذا أجــاب لــذا قــررت رفــع اجللســة حتــى حضــور ‪ .........‬شــخصيا‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا … القاضــي يف احملكمــة العامــة‬\n‫بالريــاض اخللــف لفضيلــة الشــيخ ‪ ....‬بنــاء علــى خطــاب رئيــس احملكمــة‬\n‫العامــة بالريــاض رقــم ‪ 9003‬وتاريــخ ‪1433/3/20‬ه ـ ففــي يــوم الســبت‬\n‫املوافــق‪ 1433/04/03‬ه ـ حضــر املدعــى وكالــة واملدعــي أصالــه ولــم‬\n‫حتضــر املدعــى عليهــا أو وكيلهــا الشــرعي وقــد ارفــق الوكيــل‬\n‫‪ ........................‬طلبــا يتضمــن تعــذر حضــور موكلتــه بهــذه اجللســة‬\n‫وطلــب حتديــد موعــد آخــر بعــد ذلــك جــرى عــرض مــادون ســابقا علــى‬\n‫املدعــي أصالــة فصــادق عليــه جملــة وتفصيــا وقــال أنــا اطلــب ميــن‬\n\n\n                                                                                           ‫‪44‬‬\n\f     ‫املدعــى عليهــا ولــذا جــرى رفــع اجللســة وســيتم إفهــام املدعــى عليهــا‬\n     ‫باحلضــور ألداء اليمــن وأنهــا تعــد ناكلــة عنــد عــدم احلضــور وذلــك‬\n     ‫اســتنادا علــى املــادة التاســعة بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n     ‫ويف يــوم الثالثــاء املوافق‪1433/05/04‬ه ـ حضــر املدعــي أصالــة‬\n     ‫واملدعــي وكالــة و حضــر حلضورهمــا ‪ ..................‬ســعودي اجلنســية‬\n     ‫ال عــن ‪....................‬‬\n                               ‫مبوجــب الســجل املدنــي رقــم ‪ ..............‬بصفتــه وكي ً‬\n     ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالريــاض برقــم‬\n     ‫‪ 24124‬وتاريــخ ‪ 1433/03/26‬ه ـ املخــول لــه فيهــا حــق املرافعــة‬\n     ‫واملدافعــة و ســماع الدعــاوى و الــرد عليهــا و اإلقــرار و اإلنــكار وبســؤال‬\n     ‫املدعــى عليــه وكالــة عــن موكلتــه قــال أنــا أول مــرة أحضــر للمحكمــة‬\n     ‫و هــي كبيــرة يف الســن و أطلــب االطــاع على الدعــوى وبعرض الدعوى‬\n     ‫عليــه قــال مــا ذكــره املدعــي يف دعــواه غيــر صحيــح و إمنــا الصحيــح أن‬\n     ‫املدعــي حضــر ملوكلتــي لتنظيــم الزوائــد و قبلــت موكلتــي قيامــة بهــذا‬\n     ‫العمــل دون اتفــاق علــى مبلــغ معــن وبعــد مــدة حضــر املدعــي ملوكلتــي و‬\n     ‫طلــب منهــا مبلغـ ًا قــدره ‪ 3.000000‬ريــال وقــال أن لــه منهــا مبلغـ ًا قــدره‬\n     ‫خمســمائة ألــف ريــال و الباقــي إلكمــال املعاملــة يف البلديــة فرفضــت‬\n     ‫موكلتــي ذلــك ومت إلغــاء الوكالــة قبــل إكمــال املعاملــة كاملــة وقــد‬\n     ‫أكملــت موكلتــي املعاملــة و ال أعلــم األعمــال التــي قــام بهــا هكــذا‬\n     ‫ذكــر وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا مت ذكرتــه ســابق ًا‬\n     ‫و أنــا أكملــت املعاملــة ولــم يتبــق إال اإلفــراغ ولــدي مــا يثبــت ذلك هكذا‬\n     ‫ذكــر وأبــرز صــورة ورقــة محضــر اللجنــة الفنيــة رقــم (‪ )848‬وباإلطــاع‬\n     ‫عليــه وجدتــه يتضمــن تســوية حــدود قطــع األراضــي مــع الشــواطر للبلــك‬\n     ‫‪ 46‬مــن املخطــط ‪ 2889‬اململــوك بالصــك رقــم ‪ 1/52‬يف ‪1396/06/04‬‬\n\n\n‫‪45‬‬\n\f‫ه ـ والواقعــة علــى طريــق امللــك عبــد اهلل ومشــار يف أســفل الورقــة إلــى أنه‬\n‫متــت املوافقــة علــى دمــج الشــوطار وتســوية احلــدود بنــاء علــى محضــر‬\n‫االتفــاق الــذي مت بــن األمانــة ومندوب ‪ .............‬املؤرخ يف ‪1430/03/12‬‬\n‫ه ـ كمــا أبــرز املدعــي وكالــة صــوره ورقــة موعــد إفــراغ و باالطــاع‬\n‫عليهــا وجدتهــا صــورة موعــد لكتابــة العــدل االولــى بتاريــخ‬\n‫‪ 1431/03/29‬ه ـ لــدى كاتــب العــدل ‪ ......................‬للصــك رقم ‪1/52‬‬\n‫و املســتفيد ‪ .................‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال أنــا‬\n‫ســأعرض األوراق علــى موكلتــي هكــذا ذكــر والنتهــاء وقــت اجللســة‬\n‫جــرى رفعهــا و أفهمــت املدعــى عليــه وكالــة بإحضــار موكلتــه يف‬\n‫اجللســة القادمــة ألداء اليمــن و أنهــا تعــد ناكلــة إذا لــم حتضــر ويف يــوم‬\n‫الســبت املوافــق‪ 1433/05/29‬ه ـ حضــر املدعــي أصالــة و املدعــي‬\n‫وكالــة و املدعــى عليــه وكالــة ‪ .....‬وبســؤال املدعــى عليــه وكالــة عــن‬\n‫ا أمــا ماجــاء يف محضر‬    ‫األوراق املقدمــة يف اجللســة الســابقة فأجــاب قائـ ً‬\n‫اللجنــة فهــو صحيــح و هــو إجــراء روتينــي غيــر مؤثــر و يســتطيع القيــام‬\n‫بــه أي شــخص و أمــا ورقــة املوعــد فهــي صحيحــة و ابــن أخــت موكلتــي‬\n‫‪ ................‬قــام مبراجعــة كتابــة العــدل وإكمــال الــازم حيــال املعاملــة‬\n‫لوجــود خطــأ يف املســاحة ثــم خاطــب امــن امانــة منطقــة الريــاض‬\n‫إلكمــال الــازم و املدعــي قــام بتقــدمي األوراق للبلديــة ثــم قــام بطلــب‬\n‫مبلــغ مــن املــال قــدره مائــة وســبعة و ثالثــون ألــف ريــال مــن أجــل إعــداد‬\n‫مســح لــأرض فقامــة موكلتــي بتســليم املبلــغ للمدعــي هــذا مــا قــام بــه‬\n‫املدعــي فقــط و املعاملــة متــت إجــراءا تهــا بعــد ذلــك دون احلاجــة ملراجعــة‬\n‫املدعــي هكــذا ذكــر بعــد ذلــك جــرى ســؤال املدعــى عليــه وكالــة عــن‬\n‫موكلتــه فقــال موكلتــي كبيــرة يف الســن و لــن حتضــر للحلــف هكذا‬\n\n\n                                                                                         ‫‪46‬‬\n\f     ‫ذكــر وبســؤاله عــن الشــخص الــذي قــام مبتابعــة املعاملــة مــن قبــل‬\n     ‫ا الشــخص‬     ‫األميــرة حتــى ورود املعاملــة لكتابــة العــدل فأجــاب قائ ـ ً‬\n     ‫الــذي قــام بذلــك هــو ‪ ................‬هكــذا ذكــر و بعــرض ذلــك علــى‬\n     ‫املدعــي قــال الصحيــح مــا ذكرتــه و ‪ ............‬تابــع املعاملــة بعــد ورودهــا‬\n     ‫إلــى كتابــة العــدل وقبــل ذلــك أنــا الوحيــد الــذي كنــت أتابــع املعاملــة و‬\n     ‫عمل املخططات لألرض وأنا حصل لي حادث ســيارة يف ‪1430/5/4‬هـ‬\n     ‫وعهــدت إلــى ‪ ..............‬صاحــب مكتــب ‪ ....‬ملراجعــة املعاملــة لــدى اللجنة‬\n     ‫الفنيــة باألمانــة كمــا أن بدايــة املعاملــة كانــت مــن بلديــة الروضــة وبقية‬\n     ‫لديهــم مــدة ســنة تقريب ـ ًا حتــى أحيلــت رســمي ًا لقســم األراضــي هكــذا‬\n     ‫ذكــر بعــد ذلــك أفهمــت املدعــى عليــه وكالــة بإحضــار وكالــة املدعــو‬\n     ‫‪ ...........‬و وكالــة ‪ .................‬والإفــادة عــن قيمــة األرض إن كانــت قــد‬\n     ‫ا ‪ ..................‬ليــس لديــه وكالــة ومســتعد بإحضــار‬     ‫بيعــت فأجــاب قائـ ً‬\n     ‫وكالــة ‪ ..........‬وبيــان قيمــة األرض هكــذا ذكــر وســيتم الكتابــة‬\n     ‫لبلديــة الروضــة لإلفــادة عــن الوكيــل الــذي كان يراجــع يف املعاملــة‬\n     ‫علمـ ًا أنــه مت الكتابــة ألمانــة منطقــة الريــاض لإلفــادة مبوجــب خطابنــا‬\n     ‫رقــم ‪ 33/851188‬يف ‪ 1433/05/04‬ه ـ ولــم تــرد اإلفــادة حتــى تاريخــه‬\n     ‫و النتها ء وقت اجللسة جرى رفعها ويف يوم اإلثنني املوافق‪1433/06/23‬‬\n     ‫ه ـ حضــر املدعــي واملدعــى عليــه وكالــة وقــد وردنــا خطــاب رئيــس‬\n     ‫بلديــة الروضــة رقــم ‪ 1433/141535‬يف ‪1433/6/22‬هـ اجلوابي خلطابنا‬\n     ‫رقــم ‪ 331014611‬يف ‪1433/5/29‬ه ـ وقــد تضمــن خطــاب رئيــس بلديــة‬\n     ‫الروضــة أن املواطــن ‪ ...............‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n     ‫‪ .................‬هــو مــن قــام مبراجعــة بلديــة الروضــة وإنهــاء إجــراءات‬\n     ‫املعاملــة اخلاصــة بعقــار ‪ ....................‬الواقــع علــى طريــق ‪ ...‬بحــي ‪...‬‬\n\n\n‫‪47‬‬\n\f‫مبوجــب وكالــة شــرعية رقــم ‪ 7951‬يف ‪1430/1/24‬هـ وبســؤال املدعى‬\n‫عليــه عمــا طلــب منــه فقــال نســيت إحضــار الوكالــة وأمــا مبلــغ بيــع‬\n‫األرض فلــم أســأل موكلتــي عــن ذلــك هكــذا أجــاب وحتــى تاريخــه لــم‬\n‫تردنــا إفــادة أمانــة منطقــة الريــاض بعــد ذلــك جــرى ســؤال الطرفــن‬\n‫ألديكمــا زيــادة أقــوال فقــال املدعــي ليــس لــدي ســوى مــا ذكــر ســابقا‬\n‫وقــال املدعــى عليــه وكالــة لــدي شــاهدين هكــذا ذكــرا وبســؤال‬\n‫املدعــى عليــه وكالــة عــن الشــاهدين ومــاذا سيشــهدون عليــه فأجــاب‬\n‫قائــا الشــهود همــا ‪ ......................‬و‪ .................‬وهمــا يشــهدان بــأن‬\n‫املدعــي حضــر إلــى وكيــل موكلتــي ‪.......................‬وأفــاد بــأن لــه‬\n‫خمســمائة ألــف والباقــي ســتذهب للبلديــة هكــذا ذكــر وأحضــر‬\n‫الشــاهد ‪ .................‬ســعودي مبوجــب ســجل مدنــي رقــم ‪.......................‬‬\n‫وبســؤاله عــن عمــره وعملــه ومقــر ســكنه وقرابتــه للطرفــن ومــا لديــه‬\n‫مــن شــهادة فأجــاب قائــا عمــري ‪ 45‬وأعمل يف وزارة اخلارجية وأســكن‬\n‫‪ ...‬وال قرابــة لــي مــع الطرفــن وأشــهد بأنــه قبــل شــهر رمضــان مــن العــام‬\n‫املاضــي ‪1432‬ه ـ حضــر املدعــي مــع ابنــه إلــى منــزل ‪ ..................‬وكان‬\n‫معنــا ‪ ...............‬وقــد ســأل ‪ ...............‬املدعــي عــن األرض ومتــى ســتنتهي‬\n‫إجراءاتهــا نظــرا لوجــود مشــتري فقــال املدعــي ل‪ .........‬إن شــاء اهلل يف‬\n‫القريــب العاجــل وخــال ثالثــة أشــهر ســيتم االنتهــاء مــن املعاملــة كمــا‬\n‫ذكــر لــه بــأن احلصــة األكبــر مــن حقوقــه ســتذهب للبلديــة ومهندســيها‬\n‫هكــذا شــهد وبســؤال الشــاهد عــن املبالــغ فقــال ال أذكــر املبالــغ‬\n‫هكــذا ذكــر وبعــرض الشــاهد ومــا جــاء يف شــهادته علــى املدعــي‬\n‫فقــال الشــاهد ال أعرفــه ومــا ذكــره مــن تقابلنــا يف منــزل ‪ ......‬صحيــح‬\n‫وهــو كان يطلــب شــراء األرض ومــا ذكــر مــن قولــي ل‪.........‬بــأن احلصــة‬\n\n\n                                                                                         ‫‪48‬‬\n\f     ‫األكبــر مــن أتعابــي ســتذهب للبلديــة ومهندســيها غيــر صحيــح هكــذا‬\n     ‫ذكــر والنتهــاء وقــت اجللســة جــرى رفعهــا وأفهمــت املدعــى عليــه وكالــة‬\n     ‫بإحضــار إجابــة علــى مــا طلــب منــه يف اجللســة الســابقة ويف يــوم األربعــاء‬\n     ‫املوافــق‪ 1433/07/16‬ه ـ حضــر املدعــي اصالــة واملدعــي وكالــة‬\n     ‫‪ .............‬ولــم يحضــر املدعــى عليهــا أووكيلهــا وقــد تقــدم الوكيــل‬\n     ‫بطلــب تأخيــر اجللســة إلــى مــا بعــد الظهــر لوجــود جلســة لديــه هــذا وقــد‬\n     ‫وردنــا إفــادة مديــر عــام االراضــي واملمتلــكات باالمانــة رقــم‬\n     ‫‪ 1433/110440‬يف ‪1433/6/25‬ه ـ تتضمــن بــأن املدعــي هــو من كان‬\n     ‫يراجــع االمانــة بخصــوص الزوائــد املشــار إليهــا يف محضــر اللجنــة الفنية‬\n     ‫رقــم ‪ 848‬واألعمــال التــي قــام بهــا فهــي تعقيــب املعاملــة ضمــن األطــر‬\n     ‫اإلداريــة والتنظيميــة مثلــه مثــل الــوكالء الشــرعيني ومرفــق صــور مــن‬\n     ‫احملاضــر بعــد ذلــك قــال املدعــي الشــاهد احلاضــر يف اجللســة الســابقة‬\n     ‫ذكــر أن االجتمــاع كان يف عــام ‪1432‬ه ـ والصحيــح أنــه كان يف عــام‬\n     ‫‪1431‬ه ـ وأنــا ال مانــع لــدي مــن احلضــور بعــد صــاة الظهــر الســتكمال‬\n     ‫الدعــوى هكــذا ذكــر ولــذا جــرى رفــع اجللســة وســيتم اســتكمال‬\n     ‫النظــر بعــد صــاة الظهــر مــن هــذا اليــوم ومت إقفــال اجللســة الســاعة‬\n     ‫احلاديــة عشــر والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه وســلم ويف متــام الواحــدة ظهــرا حضــر املدعــي أصالــة‬\n     ‫واملدعــي وكالــة ولــم يحضــر املدعــى عليــه رغــم تعهــده باحلضــور وســيتم‬\n     ‫الكتابــة إلــى كتابــة العــدل األولــى بالريــاض لإلفــادة عــن تاريــخ ورود‬\n     ‫املعاملــة إليهــم والصــك الصــادر فيهــا ومتــى بيعــت األرض ومبلــغ البيــع‬\n     ‫ومــا مت مــن إجــراءات لديهــم حيــال هــذه األرض وحتــى الكتابــة وورود‬\n     ‫اإلجابــة جــرى رفــع اجللســة ويف يــوم األحــد املوافــق‪ 1433/09/03‬ه ـ‬\n\n\n‫‪49‬‬\n\f‫حضــر املدعــي وأفــاد بــورود إفــادة كتابــة العــدل وباالطــاع علــى‬\n‫املعاملــة وجــدت بهــا إفــادة رئيــس كتابــة العــدل األولــى بالريــاض رقــم‬\n‫‪ 331553718‬يف ‪1433/8/24‬ه ـ املتضمنــة أن املعاملــة قيــدت برقــم ‪8‬‬\n‫‪ 1431/1699‬ودمجــت مــع املعاملــة رقــم ‪ 1431/36062‬وصــدرت إلــى‬\n‫األراضــي واملمتلــكات يف ‪1432/7/13‬ه ـ ا‪.‬هــ‪ .‬ولــم يتضمــن اخلطــاب‬\n‫بيــان قيمــة بيــع العقــار واالجــراءات التــي متــت عليهــا أثنــاء بقائهــا حتــى‬\n‫خروجهــا إلــى األراضــي واملمتلــكات ولــذا ســيتم الكتابــة مجــددا‬\n‫لإلفــادة عــن ذلــك وحتــى ورود اإلجابــة جــرى رفــع اجللســة ويف يــوم‬\n‫الســبت املوافــق‪ 1433/12/25‬ه ـ حضــر املدعــي وأفــاد بــورود إفــادة‬\n‫كتابــة العــدل وباالطــاع علــى املعاملــة وجــدت بهــا خطــاب رئيــس‬\n‫كتابــة العــدل األولــى بالريــاض رقــم ‪ 332024491‬يف ‪1433/12/1‬ه ـ‬\n‫ولــذا حــدد املوعــد القــادم يــوم الســبت ‪1434/2/16‬ه ـ الســاعة ‪11.00‬‬\n‫ويف يــوم الســبت املوافــق‪ 1434/02/16‬ه ـ حضــر املدعــي أصالــة‬\n‫واملدعــى عليــه وكالــة وباالطــاع علــى خطــاب رئيــس كتابــة العــدل‬\n‫األولــى بالريــاض واملشــار إليــه وجدتــه يتضمــن (أنــه بإحالــة املعاملــة‬\n‫ملديــر قســم احلاســب اآللــي بهــذه اإلدارة أفــاد أن الصــك رقــم ‪ 1/52‬يف‬\n‫‪1496/6/4‬ه ـ منتقــل ومت إصــدار صــك برقــم ‪ 910113033828‬يف‬\n‫‪1431/6/3‬ه ـ مببلــغ وقــدره ‪ 89773370‬ريــال والصــك رقــم‬\n‫‪ 310114018660‬يف ‪1431/9/13‬هـ مت بيعه مببلغ وقدره ‪11527560‬‬\n‫ريــال مببلــغ وقــدره ‪ 101300930‬ريــال علمــا بــأن صحــة تاريــخ الصــك‬\n‫رقــم ‪ 1/52‬يف ‪1396/6/4‬ه ـ ) وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n‫قــال ماذكــر يف خطــاب كتابــة العــدل ال أثــر لــه يف الدعــوى وأمــا‬\n‫خطــاب األمانــة فصحيــح ولكــن املدعــي وكيــل يف املراجعــة وإيصــال‬\n\n\n                                                                                        ‫‪50‬‬\n\f     ‫املعلومــة وذلــك يف بدايــة املعاملــة حيــث انتهــى عمــل املدعــي بعــد إعــداد‬\n     ‫التقريــر الهندســي هكــذا ذكــر بعــد ذلــك قــال املدعــى عليــه وكالــة‬\n     ‫لــدي شــاهد واطلــب ســماع شــهادته وأحضــر للشــهادة ‪.................‬‬\n     ‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ...................‬وبســؤاله عــن‬\n     ‫عمــره وعملــه ومقــر ســكنه وقرابتــه ألطــراف الدعــوى ومــا لديــه مــن‬\n     ‫شــهادة فقــال عمــري ‪63‬ســنة وأعمــل األن وكيــا ل‪ .....................‬الــذي‬\n     ‫هــو ابــن اخــت املدعــى عليهــا واســكن يف حــي ‪ ....‬وال قرابــة لــي مــع‬\n     ‫أطــراف الدعــوى وأشــهد بأنــه قبــل ســنتني أو ســنة ونصــف تقريبــا‬\n     ‫حضــر املدعــي ملنــزل ‪ .................‬وكنــت حاضــرا ومعنــا ‪................‬‬\n     ‫وبحضــور ‪ .............‬وقــد ذكــر املدعــي بانــه متفــق مــع مهندســي األمانــة‬\n     ‫علــى ان يعطيهــم مبلغــا قــدره ‪ 3000000‬وأن لــه ‪ 500000‬ريــال وأن‬\n     ‫هنــاك عقــد مــع محامــي فطلــب ‪ ...............‬حضــور احملامــي فقــال لــه‬\n     ‫املدعــي احملامــي يف جــدة ورفــض ‪ ............‬إعطــاء املدعــي هــذا املبلــغ‬\n     ‫هكــذا شــهد وبعــرض الشــاهد وماجــاء يف شــهادته علــى املدعــي فقــال‬\n     ‫الشــاهد ليــس وكيــا لــل‪ ...........‬وإمنــا يعمــل يف القصــر وماجــاء يف‬\n     ‫شــهادته كلــه غيــر صحيــح والصحيــح أننــي اجتمعت مــع ‪ ...........‬وطلبت‬\n     ‫منــه أتعابــي البالــغ قدرهــا ‪ 3000000‬ريــال وخوفــا مــن جحــد ‪................‬‬\n     ‫ألتعابــي وعــدم ســداد املبلــغ لــي نظــرا لقــرب انتهــاء املعاملــة قلــت لــه بــأن‬\n     ‫املهنــدس الــذي هــو يعمــل يف مكتــب ‪ ...‬معــي مــن أجــل حثــه علــى ســداد‬\n     ‫املبلــغ هكــذا ذكــر بعــد ذلــك جــرى ســؤال الطرفــن ألديكمــا زيــادة‬\n     ‫أقــوال أو بينــات فقــال املدعــي ليــس لــدي ســوى مــامت ذكــره وقــال‬\n     ‫املدعــى عليــه وكالــة ليــس لــدي ســوى ماذكــر وأطلــب إحالــة املدعــي‬\n     ‫ملجازاتــه مــع موظفــي األمانــة علــى الرشــوة هكــذا ذكــر بعــد ذلــك‬\n\n\n‫‪51‬‬\n\f‫والنتهــاء أقــوال اخلصــوم وبيناتهــم جــرى قفــل بــاب املرافعــة وحــدد موعــد‬\n‫لنطــق احلكــم يــوم الثالثــاء ‪1434/4/9‬ه ـ الســاعة الثامنــة ويف يــوم‬\n‫الثالثــاء املوافــق‪ 1434/04/09‬ه ـ حضــر املدعــي أصالــة ولــم يحضــر‬\n‫املدعــى عليــه وبســؤال املدعــي عــن املبلــغ املســلم لــه مــن املدعــى عليهــا‬\n‫البالــغ قــدره مائــة وســبعة وثالثــون ألــف ريــال فقــال املبلــغ صحيــح وهــو‬\n‫مقابــل إعــداد املخطــط والرســومات الهندســية وال مانــع لــدي مــن‬\n‫إحتســابه مــن أتعابــي قطعــا للنــزاع هكــذا ذكربعــد ذلــك ومبــا أن‬\n‫املدعــى عليهــا قــد امتنعــت عــن اداء اليمــن رددت اليمــن علــى املدعــي‬\n‫فحلــف قائــا (واهلل العظيــم بأننــي اتفقــت مــع املدعــى عليهــا على تنظيم‬\n‫الزوائــد للعقــار العائــد إليهــا واململــوك بالصــك رقــم ‪ 1/52‬يف‬\n‫‪1396/6/4‬ه ـ مقابــل أتعــاب قدرهــا ثالثــة ماليــن ريــال وقــد قمــت‬\n‫بالعمــل لوحــدي واهلل العظيــم) فبنــاء علــى مــا تقــدم ومبــا أن املدعــى‬\n‫عليــه وكالــة يف اجللســة الثانيــة صــادق علــى اتفــاق موكلتــه مــع املدعــي‬\n‫علــى تنظيــم الزوائــد للعقــار العائــد إليهــا بالصــك رقــم ‪ 1/52‬يف‬\n‫‪1396/6/4‬ه ـ وأنكــر االتفــاق علــى أتعــاب املدعــي ومبــا أن املدعــي ال‬\n‫بينــة لديــه علــى أجــرة األتعــاب ولقولــه صلــى اهلل عليــه وســلم (البينــة‬\n‫علــى املدعــي واليمــن علــى مــن أنكر)ومبــا أن املدعــى عليهــا امتنعــت‬\n‫عــن أداء اليمــن تعــد توجههــا عليهــا يف قــدر مبلــغ األتعــاب البالــغ قــدره‬\n‫ثالثــة ماليــن ريــال ومبــا أن الراجــح هــو رد اليمــن علــى املدعــي عنــد‬\n‫نكــول املدعــى عليهــا عــن أداء اليمــن قــال ابــن القيــم يف الطــرق‬\n‫احلكمية(قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل ورضــي اهلل عنــه‬\n‫وليــس املنقــول عــن الصحابــة رضــي اهلل عنهــم بالنكــول ورد اليمــن‬\n‫مبختلــف بــل هــذا لــه موضــع وهــذا لــه موضــع فــكل موضــع أمكــن‬\n\n\n                                                                                      ‫‪52‬‬\n\f     ‫املدعــي معرفتــه والعلــم بــه رد املدعــى عليــه اليمــن فإنــه إن حلــف‪-‬أي‬\n     ‫املدعــي‪ -‬اســتحق وإن لــم يحلــف لــم يحكــم لــه بنكــول املدعــى عليــه‬\n     ‫وهــذا كحكومــة عثمــان واملقــداد فــإن املقــداد قــال لعثمــان احلــف أن‬\n     ‫الــذي دفعتــه إلــي كان ســبعة آالف وخذهــا فــإن املدعــي هنــا ميكنــه‬\n     ‫معرفــة ذلــك والعلــم بــه كيــف وقــد ادعــى بــه فــإذا لــم يحلــف لــم يحكــم‬\n     ‫لــه إال ببينــة أو إقــرار) ومبــا أن املدعــي أدى اليمــن بعــد طلبهــا منــه‬\n     ‫بالصيغــة املشــار إليهــا بعاليــه ومبــا أن املدعــي أثبــت قيامــه بالعمــل املتفق‬\n     ‫عليــه وذلــك مبوجــب ‪-1‬محضــر اللجنــة الفنيــة رقــم ‪ -2 848‬موعــد‬\n     ‫اإلفــراغ للعقــار بعــد التنظيــم يف ‪1431/3/29‬ه ـ ‪-3‬خطــاب بلديــة‬\n     ‫الروضــة رقــم ‪1433/141535‬ه ـ يف ‪1433/6/22‬ه ـ املشــار إليــه‬\n     ‫‪-4‬إفــادة مديــر عــام األراضــي واملمتلــكات باألمانــة رقــم‬\n     ‫‪1433/110440‬ه ـ يف ‪1433/6/25‬ه ـ ومبــا أن شــهادة الشــاهدين‬\n     ‫اللذيــن أحضرهمــا املدعــى عليــه وكالــة تثــب أن املدعــي هــو مــن قــام‬\n     ‫بالعمــل وأنــه متابــع للمعاملــة يف التاريــخ الــذي مت اللقــاء بــه مــع ‪............‬‬\n     ‫يف شــهر رمضــان مــن عام‪1432‬ه ـ وبنــاء علــى كالم املدعــي يف عــام‬\n     ‫‪1431‬ه ـ وليــس ‪1432‬ه ـ ومبــا شــهادة شــاهدي املدعــى عليــه غيــر مؤثــرة‬\n     ‫ألن مقتضاهــا طلــب املدعــي مبالــغ أتعابــه وأمــا الرشــوة فغيــر ثابتــة ألن‬\n     ‫املبالــغ لــم تســلم للمدعــي كمــا أن الشــهود شــهادتهم يعتريهــا النقــص‬\n     ‫لعــدم تذكــر األول للمبالــغ وعــدم تأكــده مــن تاريــخ االجتمــاع والثانــي‬\n     ‫وكيــل عــن ‪.............‬الــذي هــو وكيــل للمدعــى عليهــا ومبــا أن املدعــى‬\n     ‫عليــه وكالــة قــرر أن املدعــو‪ ................../‬هــو مــن قــام مبتابعــة املعاملــة‬\n     ‫حتــى ورودهــا لكتابــة العــدل وأنــه ليــس لديــه وكالــة رســمية عــن‬\n     ‫‪ ............‬ومبــا أنــه ميتنــع عــادة قبــول اجلهــات احلكوميــة اســتقبال أي‬\n\n\n‫‪53‬‬\n\f‫شــخص ال يحمــل وكالــة رســمية عــن صاحــب العالقــة وخصوص ـ ًا يف‬\n‫املعامــات الكبيــرة كمــا أن اإلفــادات الرســمية الــواردة إلينــا تفيــد‬\n‫بخــاف ذلــك وأن املتابــع للمعاملــة هــو املدعــي فقــط ومبــا أن املدعــى‬\n‫عليــه وكالــة لــم يقــم بإحضــار وكالــة ‪ ..............‬رغــم طلبهــا منــه عــدة‬\n‫مــرات وملــا جــاء يف إفــادة فضيلــة رئيــس كتابــة العــدل األولــى بالريــاض‬\n‫املشــار إليهــا مــن أن الصــك رقــم ‪ 1/52‬يف ‪1396/6/14‬ه ـ منتقــل‬\n‫بصكــن األول يف ‪1431/6/3‬ه ـ والثانــي يف ‪1431/9/13‬ه ـ وهــو‬\n‫تاريــخ مقــارب جــدا لتاريــخ انتهــاء املعاملــة مــن األمانــة وإحالتهــا لكتابــة‬\n‫العــدل ممــا يــدل علــى أن املدعــي هــو مــن قــام بإمتــام املعاملــة وأن املتبقــي‬\n‫هــو اإلفــراغ فقــط ومبــا أن املبلــغ الــذي بيــع بــه العقــار بعد تنظيــم الزوائد‬\n‫قــد ره(‪ )101.300.930‬مــع مالحظــة عــدم إفــادة املدعــى عليــه وكالــة‬\n‫عــن بيــان املبلــغ املبــاع بــه رغــم طلــب ذلــك ومبــا أنــه باملقارنــة بــن أتعــاب‬\n‫املدعــي البالغــة ‪ 3000.000‬مــع قيمــة األرض يعــد مقبــوال إذ اليتعــدى ‪%3‬‬\n‫مــن قيمــة األرض بخــاف مــا لــو كان املبلــغ املباعــة بــه األرض قليــا‬\n‫وغيــر متناســب مــع قيمــة األتعــاب ومبــا أن املدعــي وافــق علــى خصــم‬\n‫املبلــغ املســلم لــه مــن اتعابــه وجلميــع ماتقــدم فقــد ألزمــت املدعــى عليهــا‬\n‫بــأن تدفــع للمدعــي مبلغــا قــدره مليونــان وثمامنائــة وثالثــة وســتون ألفــا‬\n‫‪ 2863000‬وبذلــك حكمــت وبعــرض احلكــم علــى املدعــي قــرر قناعتــه‬\n‫بــه وهــذا احلكــم حضــوري يف حــق املدعــى عليهــا إســتناد َا علــى الفقــرة‬\n‫األولــى مــن الالئحــة التنفيذيــة للمــادة اخلامســة و اخلمســن مــن نظــام‬\n‫املرافعــات الشــرعية وســيتم إبــاغ املدعــى عليهــا باحلكــم لتقريــر‬\n‫قناعتهــا باحلكــم مــن عدمهــا مــع إفهامهــا عنــد اعتراضهــا بــأن لهــا مــدة‬\n‫قدرهــا ثالثــون يوم ـ ًا اعتبــار ًا مــن تاريــخ اســتالمها للحكــم لتقــدمي‬\n\n\n                                                                                             ‫‪54‬‬\n\f     ‫اعتراضهــا وإذا انتهــت املــدة ولــم تقــدم اعتراضهــا فيهــا ســقط حقهــا‬\n     ‫باســتئناف احلكــم و اكتســب احلكــم القطعيــة ومت إقفــال اجللســة‬\n     ‫الســاعة ‪ 8.50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/9‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد فلــدي‬\n     ‫أنــا ‪ ........................‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n     ‫برقــم ‪ 3256388‬وتاريــخ ‪ 1432/02/26‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 32174878‬وتاريــخ ‪ 1432/02/26‬ه ـ ففــي يــوم األربعــاء‬\n     ‫املوافــق‪ 1434/06/21‬ه ـ حيــث عادت املعاملة من محكمة االســتئناف‬\n     ‫وبرفقهــا القــرار املــدون علــى ظهــر الصــك واملتضمــن مــا نصــه (‬\n     ‫تظهيــرات الدائــرة احلقوقيــة الثالثــة مبحكمــة االســتئناف بالريــاض‬\n     ‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪34183132‬‬\n     ‫وتاريــخ ‪1434/4/9‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة‬\n     ‫بالريــاض الشــيخ … وأصدرنــا القــرار رقــم ‪ 34235690‬وتاريــخ‬\n     ‫‪1434/6/10‬ه ـ املتضمــن املصادقــة علــى احلكــم واهلل املوفــق قاضــي‬\n     ‫اســتئناف ‪ .....................‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ .............‬ختمــه‬\n     ‫وتوقيعــه رئيــس الدائــرة د‪ ....................‬ختمــه وتوقيعــه ) وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n     ‫‪1434/6/21‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........................‬‬\n     ‫القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪ 3256388‬وتاريــخ‬\n     ‫‪ 1432/02/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32174878‬وتاريــخ‬\n     ‫‪ 1432/2/26‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/11/09‬ه ـ افتتحــت‬\n\n\n‫‪55‬‬\n\f‫اجللســة الســاعة (‪ )10:15‬وردنــا خطــاب رئيــس محكمــة اإلســتئناف‬\n‫رقــم ‪ 341873072‬بتاريــخ ‪1434/09/09‬ه ـ وبرفقــه القــرار رقــم‬\n‫‪ 34311738‬بتاريــخ ‪1434/09/03‬ه ـ واملتضمــن أنــه مت اإلطــاع مــن‬\n‫قبــل الدائــرة احلقوقيــة الثالثــة علــى اإللتمــاس املذكــور وعلــى كافــة‬\n‫األوراق املرفقــة املقــدم مــن ‪ .....................‬املقيــدة برقــم ‪341873072‬‬\n‫بتاريــخ ‪1434/8/2‬ه ـ املتعلــق بطلــب إعــادة النظــر يف احلكــم الصــادر‬\n‫بــه الصــك رقــم ‪ 34183132‬بتاريــخ ‪1434/04/09‬ه ـ وتقــرر الدائــرة‬\n‫بأنــه لــم يظهــر لهــا مــا يوجــب قبــول اإللتمــاس حيــث لــم يقــدم امللتمــس‬\n‫شــيئا جديــدا يســتوجب إعــادة النظــر يف احلكــم قاضــي اســتئناف‬\n‫‪...........................‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.........................‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة د‪ ............................‬ختمــه وتوقيعه وباهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪1434/11/9‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة الثالثــة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد باخلطــاب رقــم ‪ 331526222‬وتاريــخ ‪1434/5/29‬ه ـ‬\n‫املرفــق بهــا الصــك رقــم ‪ 34183132‬وتاريــخ ‪1434/4/9‬ه الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ............................. /‬املتضمــن‬\n‫احلكــم يف الدعــوى املقامــة مــن ‪ ................. /‬ضــد ‪ ..................... /‬علــى‬\n‫النحــو املوضــح بالصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل بــه وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n                          ‫وصلى اهلل على نبينا محمد وآله وصحبه وسلم ‪،،،‬‬\n\n\n                                                                                            ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":40,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fda445ddd66bbc27331413baea32789eea272792f5ade627fc07ac1bd278ec2e","normalized_text_hash":"fe2b731dc477cc3ce4c8541472ad79cc4e79dac49c68bf40906a01a8543827ae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p40-34183132"},{"id":"56d59ef7-06d9-5a0c-83f0-794b1440cad6","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسره «داللة» -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه - العامل يف اجلعالة ال يستحق اجرته إال بتمام العمل -االستخالف يف سماع شهادة الشاهد -احلكم بالزام املدعى عليه بدفع مبلغ الداللة -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبلغ املدعى عليه.","document_number":"33449382","case_number":"3285587","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/9","year":"1434","subject":"سمسره «داللة» -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه - العامل يف اجلعالة ال يستحق اجرته إال بتمام العمل -االستخالف يف سماع شهادة الشاهد -احلكم بالزام املدعى عليه بدفع مبلغ الداللة -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبلغ املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33449382 :‬تاريخه‪1433/11/9 :‬هـ‬\n                        ‫رقم الدعوى ‪3285587 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3448934‬تاريخه‪1434/2/27 :‬هـ‬\n\n\n     ‫سمســره «داللــة» ‪ -‬ســماع الدعــوى غيابيـ ًا لتعــذر تبليــغ املدعــى عليــه ‪-‬‬\n     ‫العامــل يف اجلعالــة ال يســتحق اجرتــه إال بتمــام العمــل ‪ -‬االســتخالف‬\n     ‫يف ســماع شــهادة الشــاهد ‪ -‬احلكــم بالــزام املدعــى عليــه بدفــع مبلــغ‬\n     ‫الداللــة ‪ -‬الغائــب علــى حجتــه متــى حضــر‪ -‬رفــع احلكــم حملكمــة‬\n                                            ‫االســتئناف لتعــذر تبلــغ املدعــى عليــه‪.‬‬\n\n\n\n\n                                     ‫‪ .1‬املادة ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n     ‫‪ .2‬بــاب اجلعالــة يف الفقــه « العامــل فيهــا ال يســتحق اجرتــه إال بتمــام‬\n                                                                          ‫العمــل»‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب بأنــه ســبق أن اتفــق أصالــة عــن‬\n     ‫نفســه ووكالــة عــن موكلــه مــع املدعــى عليــه علــى أن يبحــث لــه عــن‬\n     ‫مالــك قطعــة أرض جتاريــة علــى شــارع ‪ ...‬الدمــام بغــرض شــرائها منــه‬\n     ‫فتعرفــا علــى مالكهــا وأخبــراه بوجــود مشــتر لألرض فوافــق املالك على‬\n     ‫بيعهــا بثمــن قــدره ســتة ماليــن وخمســمائة ألــف ريــال ثــم وافــق املدعــى‬\n     ‫عليــه علــى شــرائها بالثمــن الــذي حــدده املالــك وأمضــى الشــراء ووعــد‬\n     ‫املدعــى عليــه املدعــي بــأن يحضــر يــوم الســبت شــيك ًا بقيمــة األرض‬\n\n‫‪57‬‬\n\f‫وشــيك ًا بكامــل الســعي ثــم تبــن أن األرض أفرغــت للمدعــى عليــه‬\n‫فأقــام دعــوى لــدى ســلف ناظــر القضيــة وحكــم لهمــا مببلــغ أربعــن‬\n‫ألــف ريــال فاعتــرض املدعــي علــى احلكــم ثــم رجــع حاكــم القضيــة‬\n‫عــن حكمــه ويطلــب إلــزام املدعــى عليــه أن يدفــع لــه وملوكلــه مبلــغ‬\n‫الســعي وقــدره مائــة واثنــان وســتون ألفـ ًا وخمســمائة ريــال هكــذا ادعــى‬\n‫‪ -‬لــم يحضــر املدعــى عليــه مــع تبلغــه لغيــر شــخصه مرتــن فجــرى ســماع‬\n‫الدعــوى غيابيـ ًا ‪ -‬جــرى ســؤال املدعــي هــل املدعــى عليــه اشــترى األرض‬\n‫بواســطة غيــره بنفــس الســعر الــذي اتفــق معــه ومــع املالــك فأجــاب بأنــه‬\n‫بنفــس الســعر وأن بينتــه هــو املالــك ويطلــب اســتخالف محكمــة الدمــام‬\n‫وذلــك لكونــه يســكن يف الدمــام ‪ -‬ورد جــواب محكمــة الدمــام بــأن‬\n‫الشــاهد لــم يحضــر كمــا لــم يحضــر املدعــي ‪ -‬جــرى الكتابــة لكتابــة‬\n‫عــدل الدمــام لإلفــادة عــن ثمــن األرض الــذي بــاع بهــا املالــك علــى املدعى‬\n‫عليــه فــورد جوابهــم بأنــه مببلــغ ســتة ماليــن وخمســمائة ألــف ريــال ‪-‬‬\n‫ومبــا أن مــا قــام بــه املدعــي وموكلــوه وســاطة عقاريــة لعقــد بيــع قطعــة‬\n‫أرض وهــذا مــن بــاب اجلعالــة ومــن أحكامهــا أن العامــل ال يســتحق فيهــا‬\n‫األجــرة إال بتمــام العمــل وهــو هنــا حصــول عقــد البيــع ‪ -‬ومبــا أن املدعــى‬\n‫عليــه أقــر بشــراء األرض بالســعر الــذي عرضــه عليــه املدعــي وهــو مــا‬\n‫أكــده جــواب كتابــة عــدل الدمــام ‪ -‬ملــا تقــدم صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بدفــع مبلــغ وقــدره مائــة واثنــان وســتون ألف ـ ًا وخمســمائة‬\n‫ريــال للمدعــي ‪ -‬هــذا احلكــم يعــد غيابيـ ًا يف حــق املدعــى عليــه والغائــب‬\n‫علــى حجتــه متــى حضــر ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة الثانيــة‬\n                                            ‫مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n                                                                                     ‫‪58‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 3285587‬وتاريخ‪1432/3/18‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32264876‬وتاريــخ ‪1432/3/18‬ه ـ ففــي يــوم األحــد‬\n     ‫املوافــق ‪1432/6/26‬ه ـ حضــر ‪ ......‬ســعودي مبوجــب ســجل مدنــي ‪......‬‬\n     ‫أصيــا عــن نفســه ووكيــا عــن ‪ ......‬ســعودي مبوجــب ســجل مدنــي رقم‬\n     ‫‪ ......‬وعــن ‪ ......‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ......‬وعــن ‪ ......‬مينــي‬\n     ‫مبوجب إقامة رقم ‪ ......‬ينوب عنهم يف املطالبة واملرافعة وإقامة الدعوى‬\n     ‫علــى ‪ ......‬وقبــول األحــكام ونفيهــا والصلــح والتنــازل واإلعتراض وطلب‬\n     ‫اليمــن وردهــا فيمــا يخــص ســعي األرض املباعــة بحــي الشــاطئ بالدمــام‬\n     ‫مبوجــب صــك وكالــة صــادر مــن كتابــة العــدل الثانيــة بالدمــام رقــم‬\n     ‫‪ 33158‬وتاريــخ ‪1427/6/2‬ه ـ ولــم يحضــر املدعــى عليــه ‪ ......‬ســعودي‬\n     ‫مبوجــب ســجل مدنــي رقــم ‪ ......‬ووردتنــا ورقــة التبليــغ رقــم ‪32265037‬‬\n     ‫وتاريــخ ‪1432/3/18‬ه ـ واملتضمنــة انــه مت إبــاغ املوظــف ‪ ......‬يف احملــل‬\n     ‫وتوقيعــه علــى االســتالم عــن طريــق محضــر اخلصــوم بهــذه احملكمــة‬\n     ‫‪ .......‬ويف يــوم األربعــاء املوافــق ‪1432/11/21‬ه ـ حضــر املدعــي ‪ ......‬ولم‬\n     ‫يحضــر املدعــى عليــه ‪ ......‬ووردنــا مــن محضــر اخلصــوم ‪ ......‬ورقــة تبليــغ‬\n     ‫املدعــى عليــه املؤرخــة يف ‪1432/6/26‬ه ـ موقعــا عليهــا باالســتالم مــن‬\n     ‫قبــل ‪ ............‬بصفتــه مســؤول اجلملــة‪ .‬وبنــاء علــى تبلــغ املدعــى عليــه لغيــر‬\n     ‫شــخصه مرتــن وبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية‬\n     ‫جــرى ســماع الدعــوى غيابيــا وبســؤال املدعــي عــن دعــواه أجــاب قائــا‪:‬‬\n\n‫‪59‬‬\n\f‫ســبق أن اتفقــت أصالــة عــن نفســي ووكالــة عــن موكلــي مــع املدعــى‬\n‫عليــه ‪ ......‬أن نبحــث لــه عــن مالــك قطعــة أرض جتاريــة علــى شــارع ‪...‬‬\n‫مدينــة الدمــام بغــرض شــرائها منــه وال أســتطيع حتديــد رقمهــا وأطوالهــا‬\n‫ومســاحتها وبعــد البحــث مــن قبلنــا تعرفنــا علــى مالكهــا وهــو ‪......‬‬\n‫فاتصلنــا بــه وأخبرنــاه بوجــود مشــتر ألرضــه املوصوفــة فوافــق املالــك‬\n‫علــى بيعهــا بثمــن قــدره ســتة ماليــن وخمســمائة ألــف ريــال وعرضنــا‬\n‫ذلــك علــى املدعــى عليــه فســامها يف بــادئ األمــر مببلــغ خمســة ماليــن‬\n‫ريــال ورفــض املالــك فوافــق املدعــى عليــه علــى شــراء األرض بالثمــن‬\n‫الــذي حــدده مالكهــا ســتة ماليــن وخمســمائة ألــف ريــال فأوقفتــه علــى‬\n‫األرض مــرة أخــرى للتأكــد مــن خلوهــا مــن أي عيــب فوقــف عليهــا‬\n‫وأمضــى الشــراء وكان هــذا يــوم اخلميــس ووعدنــي أن يحضــر يف يــوم‬\n‫الســبت شــيكا مصدقــا بكامــل ثمنهــا باســم مالكهــا وأن يحضــر‬\n‫لــي شــيكا آخــر بكامــل الســعي وســافر إلــى الريــاض محــل إقامتــه‬\n‫وملــا حضــر يــوم الســبت لــم يحضــر املدعــى عليــه عنــدي وملــا حضــر يــوم‬\n‫االثنــن أو الثالثــاء الــذي يليــه اتصــل بــي أحــد الــوكالء املشــاركني‬\n‫يف الوســاطة وقــال لــي األرض أفرغــت للمدعــى عليــه فاتصلــت ‪......‬‬\n‫بصفتــه الوســيط الــذي أحضــر املدعــي فأخبرنــي بأنــه ليــس لديــه خبــر‬\n‫ووعــد باالستفســار مــن املدعــى عليــه وبعــد ذلــك بأقــل مــن أســبوع تقريبــا‬\n‫أرســلت للمدعــى عليــه خطابــا بالفاكــس واتصلــت عليــه هاتفيــا ولــم‬\n‫يــرد فأقمــت عليــه دعــوى نظــرت لــدى ســلفكم القاضــي ‪ ......‬ثــم صــدر‬\n‫مــن فضيلتــه الصــك رقــم ‪ 28/162‬وتاريــخ ‪1428/7/9‬ه ـ بإلــزام املدعــى‬\n‫عليــه بــأن يســدد لــي وموكلــي أربعــن ألــف ريــال فقــط وصــرف النظــر‬\n‫عــن باقــي مبلــغ الســعي مائــة واثنــن وعشــرين ألــف وخمســمائة ريــال‬\n\n\n                                                                                     ‫‪60‬‬\n\f     ‫فاعترضنــا علــى احلكــم وبعــد مداولــة مــع التمييــز رجــع ســلفكم‬\n     ‫عــن حكمــه لتنظــر لــدى اخللــف مــن جديــد وصــدق مــن محكمــة‬\n     ‫التمييــز لــذا أطلــب الــزام املدعــى عليــه أن يدفــع لــي وموكلــي كامــل‬\n     ‫مبلــغ الســعي مائــة واثنــن وســتني ألــف وخمســمائة ريــال هــذه دعــواي‬\n     ‫وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى الصــك املشــار إليــه‬\n     ‫واملتضمــن مــا ذكــره املدعــي وهــذا نــص جــواب املدعــى عليــه علــى‬\n     ‫الدعــوى يف الصــك املشــار إليــه‪ ( :‬مــا ذكــره املدعــي وكالــة يف دعــواه‬\n     ‫مــن أنــي اتصلــت باملدعــو ‪ ......‬وطلبــت منــه أن يبحــث لــي عــن صاحــب‬\n     ‫األرض املذكــورة يف الدمــام فصحيــح واشــترطت عليــه بــأن ربــع الســعي‬\n     ‫‪ ......‬فوافــق علــى ذلــك أمــا أنــي أبرمــت العقــد عــن طريقــه فغيــر صحيــح‬\n     ‫وذلــك ألنــه اتصــل علــي رجــل يدعــى ‪ ......‬مــن طريــق ‪ ......‬لقــد اتفقنــا‬\n     ‫مــع صاحــب األرض بالــف وثمامنائــة ريــال للمتــر ودفعنــا العربــون علــى‬\n     ‫ذلــك فقلــت قبلــت ثــم قلــت أعطنــي اســم صاحبهــا ألجــل كتابــة الشــيك‬\n     ‫باســمه ثــم اتصــل علــي ‪ ......‬وقــال إن صاحــب األرض يرغــب يف بيعهــا‬\n     ‫مببلــغ ألــف وثمامنائــة وخمســة وثالثــون ريــاال فقلــت ال أوافــق علــى ذلــك‬\n     ‫ملــا اختلــف كالم البائــع ثــم بعــد فتــرة عــدت إلــى الدمــام ورغبــت يف‬\n     ‫شــرائها فحصــل أن اشــتريتها عــن طريــق مكتــب ‪ ...‬مببلــغ وقــدره ســتة‬\n     ‫ماليــن وخمســمائة ألــف ريــال ودفعــت لــه الســعي هــذا جوابــي ) وبعرض‬\n     ‫ذلــك علــى املدعــي أجــاب قائــا‪ :‬الصحيــح مــا ذكرتــه هكــذا أجــاب‬\n     ‫وللتأمــل وطلــب حضــور املدعــى عليــه رفعــت اجللســة ‪ .‬ويف يــوم األربعــاء‬\n     ‫املوافق‪1433/03/30‬ه ـ حضــر املدعــي ‪ ......‬ولــم يحضــر املدعــى عليــه‬\n     ‫‪ ......‬ووردنــا مــن محضــر اخلصــوم ‪ ......‬أصــل ورقــة التبليــغ بهــذه اجللســة‬\n     ‫املوجهــة للمدعــى عليــه املؤرخــة يف ‪1432/11/21‬ه ـ وقــد دون عليهــا‬\n\n\n‫‪61‬‬\n\f‫اســتالم ‪ ......‬بصفتــه عامــل وتوقيعــه وبســؤال املدعــي وكالــة هــل‬\n‫املدعــى عليــه اشــترى األرض بواســطة غيــره بالســعر نفســه الــذي اتفــق‬\n‫معــه عليــه ومــع املالــك أجــاب قائــا‪ :‬نعــم هكــذا أجــاب وبســؤاله عــن‬\n‫بينــة أجــاب قائــا‪ :‬أطلــب اســتخالف احملكمــة العامــة بالدمــام لســماع‬\n‫شــهادة املالك ‪ ......‬هكذا أجاب فأمرت بكتابة االســتخالف وأفهمت‬\n‫املدعــي بإحضــار ‪ ...... ......‬يف اجللســة القادمــة فاســتعد بذلــك لــذا رفعــت‬\n‫اجللســة‪.‬ويف يــوم الثالثــاء املوافــق ‪1433/07/01‬ه ـ حضــر املدعــي ‪......‬‬\n‫املــدون هويتــه ســابقا ولــم يحضــر املدعــى عليــه ‪ ......‬ســعودي مبوجــب‬\n‫ســجل مدنــي رقــم (‪ )......‬وحضــر ‪ ......‬ســعودي مبوجــب ســجل مدنــي‬\n‫رقــم (‪ )......‬وبتــاوة الدعــوى عليــه قــرر قائــا‪ :‬أنــا متنــازل للمدعــي ‪......‬‬\n‫عــن نصيبــي يف الســعي محــل الدعــوى إن ثبــت لديكــم هكــذا قــرر‬\n‫ووردنــا خطــاب رئيــس احملكمــة العامــة بالدمــام رقــم ‪331162633‬‬\n‫وتاريــخ ‪1433/6/21‬ه ـ املتضمــن أنــه جــرى حتديــد موعــد لســماع‬\n‫شــهادة الشــاهد ولــم يحضــر املدعــي أو شــاهده يف املوعــد احملــدد‪.‬‬\n‫وذلــك جوابــا علــى خطابنــا رقــم ‪ 33625903‬وتاريــخ ‪1433/4/5‬ه ـ‬\n‫املتضمــن اســتخالف فضيلتــه يف ســماع شــهادة ‪ .......‬وبعــرض ذلــك علــى‬\n‫املدعــي أجــاب قائــا‪ :‬ملــا طلبــت مــن الشــاهد ‪ ......‬احلضــور معــي للشــهادة‬\n‫ذكــر لــي أنــه ال يذكــر بكــم بــاع األرض محــل الدعــوى علــى املدعــى‬\n‫عليــه بســبب طــول املــدة ولــذا أطلــب الكتابــة إلــى كتابــة عــدل الدمــام‬\n‫إلفادتكــم بكــم بــاع ‪ ....‬األرض علــى املدعــى عليــه ورقمهــا ‪ ...‬حــي ‪...‬‬\n‫احلــي ‪ ...‬املجــاور ‪ ...‬وقــد استفســرت مــن كتابــة العــدل يف الدمــام هــل‬\n‫ميكــن اإلفــادة عــن ذلــك مبجــرد رقــم القطعــة واحلــي وأجابــوا أنــه ميكــن‬\n‫اجلــواب هكــذا أجــاب لــذا أمــرت بالكتابــة إلــى كتابــة عــدل الدمــام‬\n\n\n                                                                                       ‫‪62‬‬\n\f     ‫لإلفــادة عــن ثمــن األرض الــذي بــاع بــه ‪ ......‬علــى املدعــى عليــه وحلــن‬\n     ‫ورود اجلــواب رفعــت اجللســة‪ .‬ويف يــوم الثالثــاء املوافــق‪1433/11/09‬‬\n     ‫ه ـ حضــر املدعــي ‪ ......‬املــدون هويتــه ســابقا ولــم يحضــر املدعــى عليــه‬\n     ‫‪ ......‬ووردنــا جــواب رئيــس كتابــة العــدل األولــى بالدمــام املكلــف برقــم‬\n     ‫‪ 331307766‬وتاريــخ ‪1433/7/14‬ه ـ واملتضمــن مــا نصــه ‪ :‬نفيدكــم‬\n     ‫أنــه بالرجــوع إلــى ســجالتنا تبــن أن القطعــة املذكــورة مفرغــة مــن‬\n     ‫الصــك رقــم ‪ 3/22/1475‬يف ‪1420/2/3‬ه ـ بالكيفيــة املذكــورة‬\n     ‫أعــاه ومببلــغ وقــدره ســته مليــون وخمســمائة ألــف ريــال مبوجــب‬\n     ‫الضبــط رقــم ‪ 1/39/56‬يف ‪1422/10/15‬ه ـ ه ـ ‪.‬أ‪.‬ه ـ فبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى و اإلجابــة ومبــا أن مــا قــام بــه املدعــي وموكلــوه‬\n     ‫هــو وســاطة عقاريــة لعقــد بيــع قطعــة أرض وعملــه هــذا يف الفقــه مــن‬\n     ‫بــاب اجلعالــة ومــن أحكامهــا أن العامــل فيهــا ال يســتحق أجرتــه إال‬\n     ‫بتمــام العمــل ألن عقــد اجلعالــة اســتقر بتمــام العمــل وهــو هنــا حصــول‬\n     ‫عقــد البيــع ومبــا أن املدعــى عليــه أقــر بشــرائه األرض بالســعر الــذي‬\n     ‫عرضــه عليــه املدعــي وهــو مــا أكــده أيضــا جــواب رئيــس كتابــة عــدل‬\n     ‫الدمــام وتنــازل املدعــو ‪ ......‬عــن نصيبــه يف الســعي للمدعــي لــذا فقــد‬\n     ‫ألزمــت املدعــى عليــه ان يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره مائــة‬\n     ‫و اثنــان و ســتون ألفــا وخمســمائة ريــال للمدعــي ‪ ......‬نصيبــه ونصيــب‬\n     ‫‪ ......‬ومجمــوع ذلــك خمســة و ســتون ألــف ريــال و للمدعــي‪ ......‬اثنــان و‬\n     ‫ثالثــون ألــف و خمســمائة ريــال وللمدعــي ‪ ......‬اثنــان و ثالثــون ألــف و‬\n     ‫خمســمائة ريــال و للمدعــي ‪ ......‬اثنــان و ثالثــون ألــف و خمســمائة ريــال‬\n     ‫والغائــب علــى حجتــه متــى حضــر وبــه حكمــت و هــذا احلكــم غيابــي و‬\n     ‫أمــرت بإخــراج صــك مبوجبــه و إبــاغ احملكــوم عليــه بصورتــه لتقريــر‬\n\n\n‫‪63‬‬\n\f‫قناعتــه أو معارضتــه و تقدميهــا خــال ثالثــن يومــا فــإن مضــت املــدة و لــم‬\n‫يقــدم الئحــة اعتراضــه بعــد تبلغــه ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/09‬ه ـ ويف يــوم الثالثاء املوافق‬\n‫‪1434/08/16‬ه ـ لــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة بالريــاض‬\n‫القائــم بعمــل القاضــي ‪ ......‬افتتحــت اجللســة بنــاء علــى حضــور املدعــي ‪....‬‬\n‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ )......‬وقــرر قائــا‪ :‬إننــي اســتلمت‬\n‫مــن إدارة تنفيــذ األحــكام احلقوقيــة مبوجب شــيك رقم ‪ 176889‬وتاريخ‬\n‫‪1434/06 /04‬ه ـ املســحوب علــى مصــرف ‪ ......‬ممثــل ملبلــغ مائــة واثنــان‬\n‫وســتون ألفــا وخمســمائة ريــال واحملكــوم بــه لــي يف هــذه الدعــوى أطلــب‬\n‫التهميــش مبوجبــه علــى صكــه وســجله هكــذا قــرر‪ .‬ثــم أبــرز الصــك‬\n‫املشــار إليــه فوجــد طبــق مــا ذكــر‪ .‬لــذا فقــد أمــرت بالتهميــش مبوجبــه‬\n‫علــى صكــه وســجله وبــه تكــون القضيــة منتهيــة بــن الطرفــن‪ .‬وبــاهلل‬\n       ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫برقــم ‪ 23/264876‬وتاريــخ ‪1434/2/16‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ....../‬املســجل برقــم ‪......‬‬\n‫وتاريــخ ‪1433/11/9‬ه ـ اخلاصــة بدعــوى ‪ ...... /‬أصالــة ووكالــة ضــد‬\n‫‪ ....../‬وبدراســة الصــك وصــورة ضبطــه والالئحــة وأوراق املعاملــة لــم‬\n‫يظهــر مــا يوجــب املالحظــة‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                                    ‫وآلــه وســلم ‪..‬‬\n\n\n                                                                                       ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":57,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f1a3fd3fb95d6fc347f1f9a9d5f3dba4a03821c19b1e91eec08f8372ada6216a","normalized_text_hash":"aa40144d60cfa266435eb25c470ce9c0ec1a2acf891c8250bdb565ab0b9dffc5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p57-33449382"},{"id":"6158c651-eb15-59f9-93e9-c62da82a7d7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -مطالبة بأتعاب محاماة -تنظر دعوى أتعاب احملاماة عند ناظر الدعوى األصلية -املثبت مقدم على النايف -ال يقبل إقرار الوكيل إال بوكالة تخوله ذلك -وجوب الوفاء بالعقود -عدم القبول باليمن قبل احلكم ال يسقطها بعده.","document_number":"33303974","case_number":"3353625","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة يف جدة و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/17","year":"1434","subject":"أتعاب -مطالبة بأتعاب محاماة -تنظر دعوى أتعاب احملاماة عند ناظر الدعوى األصلية -املثبت مقدم على النايف -ال يقبل إقرار الوكيل إال بوكالة تخوله ذلك -وجوب الوفاء بالعقود -عدم القبول باليمن قبل احلكم ال يسقطها بعده.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪33303974:‬تاريخه‪1433/6/17 :‬هـ‬\n                       ‫رقم الدعوى‪3353625 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34201134‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n     ‫أتعــاب ‪ -‬مطالبــة بأتعــاب محامــاة ‪ -‬تنظــر دعــوى أتعــاب احملامــاة عنــد‬\n     ‫ناظــر الدعــوى األصليــة ‪ -‬املثبــت مقــدم علــى النــايف ‪ -‬ال يقبــل إقــرار‬\n     ‫الوكيــل إال بوكالــة تخولــه ذلــك ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬عــدم‬\n                               ‫القبــول باليمــن قبــل احلكــم ال يســقطها بعــده‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى {يا أيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n     ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (يقــول اهلل تعالــى‪ ،‬ثالثــة أنــا خصمهــم‬\n     ‫يــوم القيامــة وذكــر منهــم ورجــل اســتأجر أجيــر ًا فاســتوفى منــه ولــم‬\n                                                                     ‫يوفــه حقــه)‪.‬‬\n                                 ‫‪ .3‬املادة السادسة والعشرون من نظام احملاماة‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد املدعــى عليــه وكالــة بــأن موكلــة املدعــى عليــه‬\n     ‫قامــت بتوكيلــه يف املطالبــة لشــريكها ‪ ...‬وقــام برفــع دعــوى طلــب فــرز‬\n     ‫نصيبهــا يف العقــار محــل الشــراكة وطلــب إيقــاف العقــار مــن التصــرف‬\n     ‫ومت ذلــك وتوقفــت احملكمــة عــن نظــر دعــوى الفــرز حتــى إثبــات‬\n     ‫الشــراكة وصــدق التوقــف مــن محكمــة التمييــز ثــم تقــدم بدعــوى‬\n     ‫إثبــات شــراكة وصــدر حكــم لصاحلهــا بإثبــات الشــراكة وقــام‬\n\n‫‪65‬‬\n\f‫باالســتمرار ومواصلــة النظــر دعــوى الفــرز وبعــد ذلــك أنكرتــه املدعــى‬\n‫عليهــا أصالــة ويطالبهــا بتســليمه أتعابــه وقدرهــا ‪ %45‬مــن نصيبهــا يف‬\n‫العقــار ‪ -‬أجــاب املدعــى عليــه بــأن املدعــي أقــام دعــوى مماثلــه لهــذه‬\n‫الدعــوى يف محكمــة العامــة بجــدة و املدعــى عليهــا تقيــم يف احملكمــة‬\n‫العامــة يف جــدة و الدعــوى تقــام يف بلــد املدعــى عليــه كمــا أن املدعــي‬\n‫اســتلم مــن موكلتــه مبالــغ ماليــة بغيــر وجــه حــق وقــد أقامــت موكلتــه‬\n‫دعــوى ضــد املدعــي يف محكمــة جــدة ‪-‬صــادق املدعــي علــى إقامــة‬\n‫الدعــوى مبحكمــة جــدة وأن ناظــر الدعــوى أفهمــه أن الدعــوى تقــام‬\n‫أمــام احملكمــة التــي نظــرت النــزاع وهــي هــذه احملكمــة وأمــا املبالــغ‬\n‫املطالــب بهــا فهــي قــرض أقرضتــه املدعــى عليهــا وال عالقــة لــه بهــذا‬\n‫النــزاع ‪ -‬جــرى إفهــام املدعــى عليــه مبقتضــى املــادة السادســة والعشــرين‬\n‫مــن نظــام احملامــاة وأن أتعــاب احملامــي عنــد االختــاف فيهــا تنظــر مــن‬\n‫احملكمــة التــي نظــرت القضيــة األصليــة وهــي هــذه احملكمــة وطلــب‬\n‫منــه جــواب علــى الدعــوى ‪ -‬اجللســة التاليــة حضــر املدعــي ولــم حتضــر‬\n‫املدعــى عليهــا وأحضــر املدعــي شــاهدين عــدال شــرع ًا وشــهدا طبــق‬\n‫دعــواه ‪ -‬يف اجللســة التاليــة حضــر الطرفــان وأجــاب املدعــى عليه وكالة‬\n‫بــأن مــا ذكــره املدعــي مــن إقامــة موكلتــه لــه وكيــا فهــذا صحيــح‬\n‫وأنكــر االتفــاق بــن موكلتــه واملدعــي وأنــه قــام بخدمتهــا بــدون مقابــل‬\n‫حســب قولــه لهــا وقــد أقــام دعــوى اثبــات الشــراكة شــخص يدعــى ‪...‬‬\n‫وكيــا ملوكلتــي وحكــم للوكيــل اآلخــر واملدعــي قــد اســتلم مــن‬\n‫موكلتــي مبلــغ وقــدره ثالثمائــة وســبعون ألــف ريــال ولــم يبــق للمدعــي‬\n‫يف ذمــة موكلتــي أي شــيء ‪ -‬أجــاب املدعــي بــأن املبلــغ املســتلم عبــارة‬\n‫عــن قــرض أقرضــه للمدعــى عليهــا ‪ -‬أنكــر املدعــى عليــه وكالــة ذلــك‬\n\n\n                                                                                  ‫‪66‬‬\n\f     ‫ليــس للمدعــي بينــة علــى أنــه قــرض ‪ -‬قــرر املدعــى عليــه وكالــة بــأن‬\n     ‫العقــار محــل النــزاع يف الدعــوى األصليــة مت بيعــه مببلــغ وقــدره خمســة‬\n     ‫عشــر مليون ـ ًا ومئتــان وخمســون ألــف ريــال ‪ -‬قــرر املدعــي أن ســبب‬\n     ‫اختــاف النســبة يف مطالبتــه وشــهادة الشــهود بــأن القضيــة أقيمــت فيهــا‬\n     ‫مرافعتــان األولــى إلثبــات الشــراكة والثانيــة طلــب الفــرز واتفقــت مــع‬\n     ‫املدعــى عليهــا عندمــا اســتلزم األمــر إقامــة دعــوى إثبــات الشــراكة أن‬\n     ‫يكــون نصيبــي (‪ )%45‬مــن قيمــة العقــار ‪ -‬ليــس للمدعــي بينــة علــى مــا‬\n     ‫ذكــره وال يقبــل بيمــن املدعــى عليهــا علــى نفيــه ‪ -‬وملــا جــاء يف شــهادة‬\n     ‫الشــاهدين الذيــن أحضرهمــا املدعــي وحيــث أقــر املدعــى عليــه بصحــة‬\n     ‫أصــل الدعــوى مــن توكيــل املدعــى عليهــا للمدعــي ووكالــة املدعــى‬\n     ‫عليــه تخولــه حــق اإلقــرار وكــذا مــا أقــر بــه مــن قيمــة بيــع موكلتــه‬\n     ‫للعقــار وبعــد االطــاع علــى ضبــط الدعــاوى التــي يطالــب املدعــي‬\n     ‫بأتعابــه فيهــا حيــث وجــدت أن أول دعــوى تقــدم بهــا املدعــي بصفتــه‬\n     ‫وكيــا عــن املدعــى عليهــا قــد ضبطــت بتاريــخ ‪1429/6/3‬ه ـ ‪ -‬كمــا‬\n     ‫أن آخــر جلســة حضرهــا املدعــي بصفتــه وكيــا للمدعــى عليهــا كان‬\n     ‫يف ‪1432/10/14‬ه ـ كمــا أن املدعــى عليهــا قــد حضــرت برفــق املدعــي‬\n     ‫يف اجللســة املنعقــدة يف ‪1432/4/20‬ه ـ ولقــول اهلل تعالــى ( يــا أيهــا الذين‬\n     ‫آمنــوا أوفــوا بالعقــود ) ولقــول النبــي صلــى اهلل عليــه وســلم (( يقــول اهلل‬\n     ‫تعالــى ‪ ،‬ثالثــة أنــا خصمهــم يــوم القيامــة وذكــر منهــم ورجــل أســتأجر‬\n     ‫أجيــرا فاســتوفى منــه ولــم يوفــه حقــه )) ‪ -‬ملــا تقــدم ثبــت أن بذمــة املدعى‬\n     ‫عليهــا للمدعــي مبلــغ وقــدره ثالثــة ماليــن وثمامنائــة واثنــا عشــر ألفــا‬\n     ‫وخمســمائة ريــال وإلزامهــا بدفعهــا للمدعــي حــا ًال وإفهــام املدعــي أن لــه‬\n     ‫ميــن املدعــى عليهــا علــى نفــي االتفــاق األخيــر ‪ -‬اعتــرض الطرفــان علــى‬\n\n\n‫‪67‬‬\n\f‫احلكــم بالئحــة ‪ -‬صــدق احلكــم بعــد مداولــة مــن الدائــرة احلقوقيــة‬\n                ‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪.....‬رئيــس احملكمــة العامــة بينبــع املســاعد وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا برقــم ‪ 3353625‬وتاريخ ‪1433/01/19‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 33138593‬وتاريــخ ‪ 1433/01/19‬ه ـ ففــي يــوم االثنــن املوافــق‬\n‫‪1433/02/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 26‬وفيهــا حضــر ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬فادعــى ضــد ‪.....‬‬\n‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪.....‬الوكيــل عــن ‪ .....‬ســعودي‬\n‫اجلنســية بالســجل رقــم ‪.....‬مبوجــب وكالــة صــادرة عــن كتابــة العــدل‬\n‫الثانيــة بشــمال جــدة بالرقــم ‪ 99873‬بتاريــخ ‪1432/11/19‬ه ـ قائــا يف‬\n‫تقريــر دعــواه إن املدعيــة قامــت بتوكيلــي يف املطالبــة لشــريكها ‪.....‬‬\n‫وقمــت برفــع دعــوى طلــب فــرز نصيبهــا يف العقــار محــل الشــراكة‬\n‫وطلبــت ايقــاف العقــار مــن التصــرف ومت ذلــك وتوقفــت احملكمــة عــن‬\n‫نظــر دعــوى الفــرز حتــى إثبــات الشــراكة وصــدق التوقــف مــن محكمة‬\n‫التمييــز ثــم تقدمــت بدعــوى إثبــات شــراكة وصــدر حكــم لصاحلهــا‬\n‫بإثبــات الشــراكة وقمــت باالســتمرار ومواصلــة النظــر دعــوى الفــرز‬\n‫وبعــد ذلــك أنكرتنــي املدعــى عليهــا وأنــا أطالب املدعى عليها بتســليمي‬\n‫أتعابــي وقدرهــا ‪ %45‬مــن نصيبهــا يف العقــار هــذه دعــواي هكــذا أدعــى‬\n‫املدعــي فجــرى ســؤاله عــن طلبــه فقــال أطلــب نصيبــي مــن قيمــة العقــار‬\n‫وال أعلــم كــم قيمــة نصيبهــا وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n\n                                                                                  ‫‪68‬‬\n\f     ‫بقولــه إن املدعــي أقــام دعــوى مماثلــه هــذه الدعــوى يف محكمــة العامــة‬\n     ‫بجــدة وذلــك مخالــف للنظــام و املدعــى عليهــا تقيــم يف مدينــة جــدة و‬\n     ‫الدعــوى تقــام يف بلــد املدعــى عليــه كمــا أن املدعي أســتلم من موكلتي‬\n     ‫مبالــغ ماليــة بغيــر وجــه حــق و قــد اقامــت موكلتــي دعــوى ضــده يف‬\n     ‫محكمــة جــدة وبعــرض ذلــك علــى املدعــي قــال إننــي بالفعــل أقمــت‬\n     ‫دعــوى امــام محكمــة جــدة العامــة بهــذا اخلصــوص و افهمنــي ناظــر‬\n     ‫الدعــوى أن الدعــوى تقــام امــام احملكمــة التــى نظــرت النــزاع فكتبــت‬\n     ‫خطــاب بالتنــازل عــن الدعــوى أمــا كــون املدعــى عليهــا تقيــم يف جــدة‬\n     ‫فــإن النــزاع عندمــا كنــت وكيــل عنهــا نظــر يف محكمــة ينبــع وأمــا‬\n     ‫املبالــغ املطالــب بهــا فهــي قــرض أقرضتــه املدعــى عليهــا وال عالقــة لــه‬\n     ‫بهــذا النــزاع وبعــرض ذلــك علــى املدعــى عليــه قــال ان محكمــة ينبــع‬\n     ‫غيــر مختصــة بنظــر الدعــوى لوجــود دعــوى يف ذات النزاع لدى محكمة‬\n     ‫جــدة فجــرى إفهامــه مبقتضــى املــادة السادســة والعشــرون مــن نظــام‬\n     ‫احملامــاة وان اتعــاب احملامــي عنــد اإلختــاف فيــه تنظــر مــن احملكمــة‬\n     ‫التــى نظــرت القضيــة ودعــوى املدعــى عليهــا األصليــة يف طلــب الفــرز‬\n     ‫وإثبــات الشــراكة نظــرت مــن قبلــي وأن احملكمــة لهــا إختصــاص يف‬\n     ‫نظــر الدعــوى وطلــب منــه جــواب علــى الدعــوى قــال أطلــب مهلــة للرجــوع‬\n     ‫ملوكلتــي للــرد علــى الدعــوى ويف يــوم األثنــن املوافــق ‪1433/2/15‬ه ـ‬\n     ‫أفتتحــت اجللســة الســاعة ‪ 11 : 11‬وفيهــا حضــر املدعــي ولــم حتضــر‬\n     ‫املدعــى عليهــا أو وكيلهــا فســألت املدعــي هــل بينــه وبــن املدعــى عليهــا‬\n     ‫عقــد فقــال ال إال ان لــدي بينــة تقيــم يف جــده وهــم كال مــن ‪.....‬و ‪.....‬‬\n     ‫اطلب أســتخالف محكمة جده لســماع شــهادتهم لذا قررت اســتخالف‬\n     ‫فضيلــة رئيــس احملكمــة العامــة بجــدة او مــن ينيــب مــن أصحــاب‬\n\n\n‫‪69‬‬\n\f‫الفضيلــة قضــاة احملكمــة لســماع الشــهادة وتزكيتهــا علــى أيــة حــال‬\n‫وحتى ورود اجلواب رفعت اجللسة ويف يوم االثنني املوافق ‪1433/3/14‬هـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 10 : 36‬وفيهــا حضــر املدعــي ولــم حتضــر‬\n‫املدعــى عليهــا وال مــن ينــوب عنهــا وقــد أحضــر املدعــي معــه املدعــو ‪.....‬‬\n‫ســعودي اجلنســية بالرقــم ‪.....‬وبســؤاله عــن مــا لديــه أجــاب قائــا أشــهد‬\n‫هلل أن املدعــى عليهــا ‪....‬وكانــت صاحبــه لوالدتــي وطلبــت منــي املدعــى‬\n‫عليهــا ان أشــهد علــى توكيلهــا ‪ ...‬علــى أن يقــوم بقســمة األرض التــى‬\n‫دخلــت بهــا املدعــى عليهــا شــريكة يف ينبــع مقابــل خمســة وعشــرين‬\n‫باملئــة مــن قيمــة العقــار هــذا مــا لــدي وبــه أشــهد كمــا أحضــر املدعــي‬\n‫املدعــو ‪.....‬ســعودي اجلنســية بالرقــم ‪.....‬وبســؤاله عــن مــا لديــه قــال أشــهد‬\n‫هلل أن يف يــوم مــن األيــام طلبــت منــي املدعــى عليهــا ‪....‬بواســطة خالتــي‬\n‫والــدة الشــاهد األول أن أحضــر لتقــوم املدعــى عليهــا ‪....‬بتوكيل املدعي‬\n‫‪.....‬وقــد حضــرت يف كتابــة عــدل محافظــة جــدة وقامــت املدعــى عليهــا‬\n‫بتوكيــل املدعــي باســتخالص نصيبهــا مــن العقــار الــذي يف ينبــع مقابــل‬\n‫خمســة وعشــرين باملئــة مــن العقــار هــذا مــا لــدي وبــه أشــهد هكــذا‬\n‫شــهد الشــاهد فطلبــت مــن املدعــي زيــادة بينــة فقــال ليــس لــدي زيــادة‬\n‫بينة فطلبت منه معدلني للشهود ويف يوم األربعاء املوافق‪1433/03/23‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر املدعــي واملدعــى‬\n‫عليــه وكالــة واجــاب املدعــى عليــه عــن دعــوى املدعــي بقولــه مــا ذكــره‬\n‫املدعــي مــن إقامــة موكلتــي لــه وكيــا فهــذا صحيــح وامــا اإلتفــاق‬\n‫فليــس بــن موكلتــي واملدعــي أي اتفــاق واملدعــي اســتلم اوراق الدعــوى‬\n‫مــن شــخص يدعــى ‪.....‬فطلبــت منــه موكلتــي بحضــور ‪.....‬حتريــر اتفــاق‬\n‫بينهمــا فقــال املدعــي أنــا اخدمكــي شــيمة منــي ومــا يأتــي منــك‬\n\n\n                                                                                        ‫‪70‬‬\n\f     ‫يكفينــي ورفــض توقيــع اتفــاق وهــذا يظهــر ســوء نيــة املدعــي ولــو كان‬\n     ‫حســن النيــة لوقــع االتفــاق وأمــا عمــل املدعــي يف الدعــوى وكالــة عــن‬\n     ‫موكلتــي فإنــه أخطــأ يف إقامــة الدعــوى حيــث أقــام يف البدايــة دعــوى‬\n     ‫فــرز وقســمة عقــار ثــم اســتلزم األمــر اثبــات الشــراكة وهــذا يظهــر عــدم‬\n     ‫معرفتــه بإقامــة الدعــوى وقــد اقــام دعــوى اثبــات الشــراكة شــخص‬\n     ‫يدعــى ‪.....‬وكيــا ملوكلتــي وحكــم للوكيــل اآلخــر واملدعــي قــد‬\n     ‫اســتلم مــن موكلتــي مبلــغ وقــدره ثالثمائــة وســبعون ألــف ريــال ولــم‬\n     ‫يبقــى للمدعــي يف ذمــة موكلتــي أي شــي هكــذا اجــاب وبعــرض ذلــك‬\n     ‫علــى املدعــي قــال مــا ذكــره املدعــى عليــه وكالــة مــن طلــب موكلتــه‬\n     ‫ابــرام اتفــاق بينــي وبينهــا وإنــي رفضــت فهــذا غيــر صحيــح وكيــف اتفــق‬\n     ‫معهــا لــدى ‪.....‬واصــا ‪.....‬وكيــا خلصمهــا ‪.....‬وقــد قمــت بتقــدمي الدعوى‬\n     ‫بطلــب الفــرز وإيقــاف صــك العقــار وأمــا اثبــات الشــراكة فإنهــا دعــوى‬\n     ‫نشــأت ألن املدعــى عليهــا لديهــا مبالــغ مــن ‪.....‬و‪.....‬فطلــب فضيلتكــم‬\n     ‫اثبــات الشــراكة وقــد تقدمــت باثبــات الشــراكة وحكــم لصاحلهــا وال‬\n     ‫عالقــة للوكيــل اآلخــر ‪ ....‬الــذي ذكــره وكيــل املدعــى عليــه وأمــا‬\n     ‫املبلــغ الــذي ذكــره املدعــى وكالــه فهــذا قــرض اقترضتــه املدعــى‬\n     ‫عليهــا منــي وال عالقــة لــه بأتعابــي وبعــرض الشــهود ومــا شــهدوا بــه علــى‬\n     ‫املدعــى عليــه قــال اطلــب مهلــة ملراجعــة موكلتــي يف أســماء الشــهود‬\n     ‫وشــهادتهم والتأكــد مــن إقامــة دعــوى الشــراكة ويف يــوم األحــد‬\n     ‫املوافــق‪ 1433/04/11‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 07‬وفيهــا‬\n     ‫حضــر املدعــي واملدعــى عليــه وكالــة وبطلــب اجلــواب مــن املدعــى عليــه‬\n     ‫وكالــة عــن الشــهود وشــهادتهم قــال إن موكلتــي ترغــب يف احلضــور‬\n     ‫ملعاينــة الشــهود ونطلــب مــن املدعــي إحضارهــم كمــا إننــي اجبــت يف‬\n\n\n‫‪71‬‬\n\f‫اجللســة املاضيــة بــأن املدعــي لــم يتقــدم بدعــوى إثبــات الشــراكة وهــذا‬\n‫غيــر صحيــح والصحيــح أن املدعــي هــو مــن قدمهــا وإمنــا دور ‪.....‬هــو‬\n‫التوجيــه واالستشــارة فقــط واطلــب إثبــات مــا ادعــاه املدعــي مــن كــون‬\n‫املبلــغ الــذي اســتلمه مــن موكلتــي وقــدره ثالثمائــة وســبعون ألــف ريــال‬\n‫لقــاء قــرض يف ذمــة موكلتــي وموكلتــي ســتحضر البينــة يف اجللســة‬\n‫القادمــة علــى عــدم ابــرام اتفــاق بــن موكلتــي واملدعــى عليــه واطلــب‬\n‫حتديــد موعــد لذلــك وبعــرض ذلــك علــى املدعــي قــال أمــا الشــهود‬\n‫فســوف اطلــب منهــم احلضــور يف اجللســة القادمــة وأمــا املبلغ الذي ســلمته‬\n‫لــي املدعيــة فهــو صحيــح اســتلمت منهــا ســبعمائة وســبعون ألــف ريــال‬\n‫وذلــك ليــس مقابــل اتعابــي وإمنــا مقابــل قــروض اقترضتهــا منــي املدعــى‬\n‫عليهــا فطلبــت منــه البينــة علــى ان املبلــغ مقابــل قــرض فقــال ليــس لــدي‬\n‫بينــة علــى ذلــك ويف يــوم الثالثــاء املوافــق‪ 1433/04/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 : 05‬وفيهــا حضــر املدعــي كمــا حضــرت املدعــى‬\n‫عليهــا ‪.....‬بالســجل املدنــي رقــم ‪.....‬املعــرف بها من قبل وكيلها الشــرعي‬\n‫احلاضــر معهــا املذكــور يف اجللســات املاضيــة فجــرى ســؤال املدعــى‬\n‫عليهــا عــن املبالــغ التــي ذكــر املدعــي انــه اقرضهــا فقالــت إنني اســتلمت‬\n‫مــن املدعــي مبلــغ وقــدره اربعمائــة ألــف ريــال قرضــة حســنة وقــد رددتهــا‬\n‫كاملــة إضافــة إلــى مبلــغ قــدره ثالثمائــة وســبعون ألــف ريــال اخذهــا‬\n‫بــدون وجــه حــق هكــذا اجابــت وبعــرض ذلــك علــى املدعــي قــال‬\n‫ماذكرتــه املدعيــة غيــر صحيــح والصحيــح أن املبلــغ كامــا مقابــل‬\n‫قــرض فطلبــت منــه البينــة فقــال إن املدعــى عليهــا قــد اقامــت دعــوى‬\n‫ضــدي تطالبنــي بــرد املبلــغ التــي اســتلمته منهــا وقــدره ســبعمائة وســبعون‬\n‫أالف ريــال وبعــرض ذلــك علــى املدعــى عليهــا اجــاب وكيلهــا قائــا إن‬\n\n\n                                                                                    ‫‪72‬‬\n\f     ‫الدعــوى التــي اقامتهــا موكلتــي يف جــدة صحيحــة إال انهــا عدلــت عنهــا‬\n     ‫لعلمهــا انهــا يف ذمتهــا للمدعــي اتعــاب وهــي تقــل عــن املبلــغ التــي تطالــب‬\n     ‫بــه فتنازلــت عــن الدعــوى لتكــون مقابــل االتعــاب وبعــرض ذلــك علــى‬\n     ‫املدعــى عليهــا صادقــت عليــه وطلبــت ســماع البينــة التــي احضرتهــا‬\n     ‫فحضــر ‪ .....‬الســعودي بالســجل املدنــي رقــم ‪.....‬وبســؤاله عمــا لديــه قــال‬\n     ‫اشــهد هلل اننــي كنــت وكيــل للمدعــى عليهــا يف عــدة قضايــا حقوقيــة‬\n     ‫وجنائيــة وزوجيــة وقــد طلبــت منــي الترافــع عنهــا يف دعــوى ضــد شــخص‬\n     ‫يدعــى ‪.....‬فأخبرتهــا ان املدعــى عليــه قــد وكلنــي يف املرافعــة عنــه وال‬\n     ‫اســتطيع املرافعــة عنهــا ثــم بعــد فتــرة حضــر لــي املدعــي هــذا احلاضــر ‪.....‬‬\n     ‫برفــق املدعــى عليهــا بواســطة إمــراءة تدعــى ‪.....‬وطلــب منــي ‪.....‬اوراق‬\n     ‫الدعــوى فســلمتها لــه وطلبــت املدعــى عليهــا ابــرام اتفــاق بينهمــا‬\n     ‫ونصحــت الطرفــن بابــرام اتفــاق تفاديــا للنــزاع مســتقبال فقــال ‪.....‬أم‬\n     ‫‪.....‬كرميــة ومعروفــة بالســخاء وانــا اتولــى الدعــوى (( مرجلــة )) والــذي‬\n     ‫تســلمه لــي انــا راضيــا بــه واشــرت عليــه ان يتقــدم بدعــوى طلــب فــرز يف‬\n     ‫البدايــة يف حــال اقــرار املدعــى عليــه ويف حــال انــكاره ترفــع دعــوى‬\n     ‫اثبــات شــراكة و قلــت لــه إننــي علــى اســتعداد يف اي مشــورة تطلبهــا‬\n     ‫منــي مســتقبال يف خصــوص هــذه الدعــوى هــذا مالــدي وبــه اشــهد‬\n     ‫هكــذا شــهد الشــاهد كمــا أحضــرت املدعيــة ‪ .....‬الســعودي بالســجل‬\n     ‫املدنــي رقــم ‪.....‬وبســؤاله عمــا لديــه قــال اشــهد هلل إننــي كنــت اعمــل‬\n     ‫رقيبــا يف الضبــط اجلنائــي يف شــرطة محافظــة جــدة و اتصلــت بــي‬\n     ‫املدعــى عليهــا واخبرتنــي انــه هنــاك مشــكلة يف الشــرطة تخصهــا‬\n     ‫فحضــرت فوجــدت هــذا احلاضــر ‪.....‬وشــخص يدعــى ‪.....‬يكــون شــقيق‬\n     ‫املدعــي وكان اإلشــكال حــول شــيكان اصدرتهــا املدعــى عليهــا‬\n\n\n‫‪73‬‬\n\f‫للمدعــي فجــرى محاولــة التوفيــق بينهمــا فرفضــوا ذلــك وســلم ‪.....‬‬\n‫الشــيكات ل‪ .....‬وقــدر مبلغهــا ســبعمائة وســبعون ألــف ريــال هذا مالدي‬\n‫وبــه اشــهد هكــذا شــهد الشــاهد وبعــرض الشــهود ومــا شــهدوا بــه علــى‬\n‫املدعــي قــال أمــا الشــهود فــا اعــرف عــن حالهــم شــيء وامــا شــهادتهم‬\n‫فغيــر صحيحيــة فقــد حضــرت ملكتــب الشــاهد األول بطلــب من املدعى‬\n‫عليهــا حيــث كان بينهمــا مطالبــة مببلــغ قــدره خمســة وســبعون ألــف‬\n‫ريــال وطلــب منــي ‪.....‬ان ابــرم عقــد مــع املدعــى عليهــا فرفضــت ذلــك‬\n‫بحجــة انــه وكيــل خلصــم املدعــى عليهــا وكيــف ابــرم عقــد معهــا‬\n‫بحضــوره وعلمــا ان الشــاهد ‪.....‬ان وكيــا للمدعــى عليهــا وقامــت‬\n‫بفســخ وكالتهــا ثــم ردهــا هكــذا قــال ثــم طلــب املدعــى عليــه وكالــة‬\n‫ســؤال املدعــي متــى علــم بشــهادة الشــهود وبعــرض ذلــك علــى املدعــي‬\n‫قــال بعــد مــا حصــل خــاف بينــي وبــن املدعــى عليهــا اخــذت احتقــق يف‬\n‫املوضــوع فتوصلــت للشــاهدين ثــم حضــر الشــاهدين الذيــن احضرهمــا‬\n‫املدعــي يف اجللســة املاضيــة فطلبــت املدعيــة ســؤال الشــاهدين هــل‬\n‫يعرفــان املدعــي ســابقا وبســؤالهما اجابــا بالنفــي فطلبــت ســؤالهما‬\n‫كيــف تعــرف عليهمــا املدعــي فأجــاب الشــاهد ‪.....‬أنــه حضــر لــه املدعي‬\n‫يف مقــر عملــه يف مطــار جــدة واجــاب اآلخــر قائــا اتصــل بــي ‪ ...‬وطلــب‬\n‫منــي الشــهادة مبــا لــدي فحضــرت هكــذا اجابــا ويف يــوم األحــد‬\n‫املوافــق‪ 1433/05/23‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 40‬وفيهــا‬\n‫حضــر املدعــي واملدعــى عليــه وكالــة وجــرى ســؤال املدعــي عــن املبلــغ‬\n‫الــذي تتدعــي املدعــى عليهــا انهــا ســلمته لــه فقــال نعــم اســتلمت مــن‬\n‫املدعــى عليهــا مبلــغ وقــدره ســبعمائة وســبعون ألــف ريــال عبــارة عــن‬\n‫قــرض اقرضتــه إياهــا ثــم جــرى ســؤال املدعــى عليــه عــن العقــار محــل‬\n\n\n                                                                                 ‫‪74‬‬\n\f     ‫النــزاع يف الدعــوى األصليــة فقــال مت بيعــه مببلــغ وقــدره خمســة عشــر‬\n     ‫مليــون ومئتــان وخمســون ألــف ريــال فســألت الطرفــن هــل لــدى أي‬\n     ‫منهمــا مــا يضيفــه فقــال املدعــي نعــم وابــرز كتابــا مــن ورقتــن يطلــب‬\n     ‫فيــه إحالــة الشــاهد ‪.....‬للجنــة املختصــة بــوزارة العــدل وذلــك لقاء حصول‬\n     ‫بعــض التجــاوز يف اداءه لعملــه وذلــك لقيامــه بالتواصــل والقيــام بعمــل‬\n     ‫استشــارة مــع طــريف النــزاع يف قضيــة واحــدة لــذا قــررت بعــث اصــل‬\n     ‫الكتــاب املذكــور لــوزارة العــدل حيــث إنهــا اجلهــة املختصــة وارفــاق‬\n     ‫نســخة منــه يف املعاملــة فســألت هــل لديــه مــا يضيفــه فقــال ال فســالت‬\n     ‫املدعــى عليــه وكالــة هــل لديــه مــا يضيفــه فقــال نعــم مــا جــاء يف شــهادة‬\n     ‫الشــهود الذيــن احضرهــم املدعــي غيــر صحيحة كما ان والدة الشــاهد‬\n     ‫‪.....‬وتدعــى ‪.....‬لهــا عالقــة باملدعــي وهــذا يســتدعي رد الشــهادة فجــرى‬\n     ‫ســؤاله عــن العالقــة ومــا وجــه رد الشــهادة فقــال مــا مصلحتهــا مــن داللــة‬\n     ‫موكلتــي علــى املدعــي كمــا ان شــهادة الشــهود وقعــت يف غيــر مجلــس‬\n     ‫العقــد فــا عبــرة بهــا كمــا ان املدعــي ذكــر انــه تعــرف علــى الشــاهد‬\n     ‫عــن طريــق مقــر عملــه والصحيــح انــه يعــرف والدتــه وهــي الســبيل‬\n     ‫األقــرب للتعــرف علــى الشــاهد مــن البحــث عنــه يف مقــر عملــه كمــا ان‬\n     ‫للمدعــي أجــر املثــل علــى عملــه فقــط وقــد اســتلم اكثــر مــن حقــه كمــا‬\n     ‫ان عــدم ابــرام عقــد مــع موكلتــي يــدل علــى ســوء نيــة املدعــي هــذا‬\n     ‫مالــدي وبعــرض ذلــك علــى املدعــي قــال امــا ‪.....‬فليــس لــي بهــا عالقــة‬\n     ‫وإمنــا كانــت زوجتــي تذهــب ملشــغل نســائي تعــود ملكيتــه للمدعــى‬\n     ‫عليهــا فذكــرت لهــا املدعــى عليــه وجــود حقــوق لهــا لــم تتمكــن مــن‬\n     ‫أخذهــا فذكــرت زوجتــي لهــا إننــي اتــوكل يف قضايــا مماثلــة وكان‬\n     ‫ذلــك يف حضــور ‪....‬وقــد انقطعــت العالقــة بعــد فســخ الوكالــة منــي‬\n\n\n‫‪75‬‬\n\f‫كمــا انــه ال يعقــل ان يكــون أجــرة املثــل مبلــغ زهيــد وانــا قــد اقرضــت‬\n‫املدعــى عليهــا قرابــة املليــون ريــال هــذا مــا لــدي وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة قــال ان املدعــي ال زال علــى عالقــة بوالــدة الشــاهد‬\n‫‪....‬هكــذا قــال فســالت الطرفــن هــل لــدى أحدكــم مــا يضيفــه فقــاال‬\n‫ال فطلبــت مــن املدعــي أحضــار معدلــن للشــاهدين يف اجللســة ويف يــوم‬\n‫اإلثنــن املوافــق‪ 1433/06/02‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 31‬‬\n‫وفيهــا حضــر املدعــي كمــا حضــرت املدعــى عليهــا ووكيلهــا واحضــر‬\n‫املدعــي معــه املدعــو ‪.....‬الســعودي بالســجل املدنــي رقــم ‪.....‬وبســؤاله‬\n‫عمــا لديــه قــال اشــهد هلل ان الشــاهد لديكــم ‪.....‬رجــل ثقــة عــدل مقبــول‬\n‫الشــهادة كمــا احضــر املدعــي معــه ‪ .....‬الســعودي بالســجل املدنــي رقــم‬\n‫‪.....‬وبســؤاله عمــا لديــه قــال اشــهد هلل أن الشــاهدين لديكــم ‪.....‬و‪.....‬‬\n‫ثقتــان عــدالن مقبولــي الشــهادة هكــذا شــهدا فطلبــت مــن املدعــي‬\n‫مزكــي للشــاهد ‪.....‬فأســتعد بذلــك وطلــب مهلــة ويف يــوم اإلثنــن‬\n‫املوافــق‪ 1433/06/09‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 35‬وفيهــا‬\n‫حضــر املدعــي واملدعــى عليــه وكالــة وأحضر املدعي معه ‪.....‬الســعودي‬\n‫بالســجل املدنــي رقــم ‪.....‬وبســؤاله عمــا لديــه قــال أشــهد هلل أن الشــاهد‬\n‫لديكــم ‪ .....‬رجــل ثقــة عــدل مقبــول الشــهادة هكــذا شــهد فجــرى‬\n‫ســؤال املدعــي ان مطالبتــه كانــت ب (‪ )%45‬مــن قيمــة العقــار وشــهادة‬\n‫الشــهود ب (‪ ) %25‬فكيــف ذلــك فقــال إن القضيــة أقيمــت فيهــا‬\n‫مرافعتــان األولــى إلثبــات الشــراكة والثانيــة طلــب الفــرز واتفقــت مــع‬\n‫املدعــى عليهــا عندمــا اســتلزم األمــر إقامــة دعــوى إثبــات الشــراكة أن‬\n‫يكــون نصيبــي (‪ )%45‬مــن قيمــة العقــار فطلبــت منــه البينــة علــى ذلــك‬\n‫فقــال ليــس لــدي بينــة وال اطلــب ميــن املدعــى عليهــا فجــرى ســؤال‬\n\n\n                                                                                   ‫‪76‬‬\n\f     ‫الطرفــن هــل لــدى أحدهمــا مــا يضيفــه فقــال املدعــى عليــه وكالــة إمنــا‬\n     ‫مــا جــاء علــى لســان الشــهود مــن أن موكلتــي ســتدفع للمدعــي (‪)%25‬‬\n     ‫مــن قيمــة العقــار فــأن ذلــك ليــس علــى ســبيل العقــد بــل هــو أشــبه مــا‬\n     ‫يكــون بالوعــد والتســويف مــع أن موكلتــي تنكــر شــهادة الشــهود‬\n     ‫متامــا كمــا أن املدعــي رفــض ابــرام العقــد مــع موكلتــي عنــد وكيــل‬\n     ‫خصمهــا بحجــة وجــود وكيــل اخلصــم وهــذا يخــص موكلتــي وخصمهــا‬\n     ‫امــا املدعــي فــا عالقــة لــه بذلــك بــل أخــذ األوراق ورفــض ابــرام عقــد‬\n     ‫فجــرى ســؤاله ملــا لــم تقــم موكلتــك برفــض توكيلــه عنــد رفضــه إجــراء‬\n     ‫العقــد فقــال بنتهــا علــى الثقــة هــذا مــا لــدي مــن إضافــة وبعــرض ذلــك‬\n     ‫علــى املدعــي مــا ذكــره املدعــى عليــه ســبق ذكــره يف اجللســات املاضيــة‬\n     ‫لــذا قــررت قفــل بــاب املرافعــة ويف يــوم الثالثــاء املوافق‪1433/06/17‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 10 : 59‬وفيهــا حضــر املدعــي كمــا حضــر‬\n     ‫املدعــى عليــه وكالــة فجــرى ســؤال املدعــي عــن املبلــغ الــذي ذكــره‬\n     ‫املدعــى عليــه وكالــة مــن أنــه قيمــة بيــع موكلتــه للعقــار فقــال إننــي‬\n     ‫اطلــب نصيبــي مــن املبلــغ الــذي ذكــره املدعــى عليــه وكالــة وهــو‬\n     ‫صحيــح فجــرى ســؤال املدعــى عليــه وكالــة عــن الوقــت الــذي بــن فســخ‬\n     ‫وكالــة املدعــي وبيــع موكلتــه للعقــار قــال إن موكلتــي قــد فســخت‬\n     ‫وكالــة املدعــي قبــل ســنتني مــن تاريــخ البيــع فجــرى ســؤاله كيــف‬\n     ‫يكــون تاريــخ البيــع يف ‪1433/1/26‬ه ـ و آخــر جلســة حضرهــا املدعــي‬\n     ‫بصفتــه وكيــا للمدعــى عليــه بتاريــخ ‪1432/10/14‬ه ـ فقــال ال أعلــم‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة وملا جاء يف شــهادة الشــاهدين‬\n     ‫‪.....‬و‪.....‬املعدلــن وحيــث أقــر املدعــى عليــه بصحــة أصــل الدعــوى مــن‬\n     ‫توكيــل املدعــى عليهــا للمدعــي ووكالــة املدعــى عليــه تخولــه حــق‬\n\n\n‫‪77‬‬\n\f‫اإلقــرار وكــذا مــا اقــر بــه مــن قيمــة بيــع موكلتــه للعقــار وبعــد اإلطــاع‬\n‫علــى ضبــط الدعــاوى التــي يطالــب املدعــي بأتعابــه فيهــا حيــث وجــدت‬\n‫أن اول دعــوى تقــدم بهــا املدعــي بصفتــه وكيــا عــن املدعــى عليهــا قــد‬\n‫ضبطــت بتاريــخ ‪1429/6/3‬ه ـ كمــا أن أخــر جلســة حضرهــا املدعــي‬\n‫بصفتــه وكيــا للمدعــى عليهــا كان يف ‪1432/10/14‬ه ـ كمــا أن‬\n‫املدعــى عليهــا قــد حضــرت برفــق املدعــي يف اجللســة املنعقــدة يف‬\n‫‪1432/4/20‬ه ـ ولقــول اهلل تعلــى ( يأيهــا الذيــن أمنــوا اوفــوا بالعقــود )‬\n‫ولقــول النبــي صلــى اهلل عليــه وســلم (( يقــول اهلل تعالــى ‪ ،‬ثالثــة أنــا‬\n‫خصمهــم يــوم القيامــة وذكــر منهــم ورجــل أســتأجر أجيــرا فاســتوفى‬\n‫منــه ولــم يوفــه حقــه )) لــكل مــا ســبق فقــد ثبــت لــدي أن بذمــة املدعــى‬\n‫عليهــا للمدعــي مبلــغ وقــدره ثالثــة ماليــن وثمامنائــة وإثنــا عشــر ألفــا‬\n‫وخمســمائة ريــال والزمتهــا بدفعهــا للمدعــي حــاال هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت واهلل اعلــم وأحكــم وأفهمــت املدعــي أن لــه ميــن املدعى عليها‬\n‫علــى نفــي االتفــاق األخيــر وبعــرض احلكــم الطرفــن قــررا اعتراضهمــا‬\n‫عليــه فجــرى تســليم كل واحــد منهمــا نســخة مــن صــك احلكــم لتقــدمي‬\n‫اعتراضــه خــال ثالثــن يومــا تبــدأ مــن تاريــخ هــذا اليــوم أن قدمــا‬\n‫اعتراضهمــا خاللهــا وإال فــإن مــن لــم يقــدم اعتراضــه يســقط حــق يف‬\n‫اإلعتــراض فيكتســب احلكــم القطعيــة يف حقــه فأبديــا فهمهــا لذلــك‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n        ‫وسلم ‪ .‬حرر يف ‪ 1433/06/17‬هـ الساعة احلادية عشر والنصف‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n‫اإلثنــن املوافــق‪ 1433/08/05‬ه ـ افتتحت اجللســة الســاعة ‪ 12.00‬وفيها‬\n‫حضــر املدعــي واملدعــى عليــه وكالــة فجــرى مني اإلطالع علــى الالئحة‬\n\n\n                                                                                       ‫‪78‬‬\n\f     ‫اإلعتراضيــة املقدمــة مــن املدعــي املقيــدة باحملكمــة رقــم ‪331311154‬‬\n     ‫بتاريــخ ‪1433/7/13‬ه ـ املكونــه مــن اربعــة أوراق مــن الئحــة اعتراضيــة‬\n     ‫وصــورة صــك احلكــم واســتعالم عــن بيانــات الــوكاالت وصــورة خطاب‬\n     ‫صــادر مــن احملكمــة ملكتــب العمــارة والهندســة وصــورة خطــاب مــن‬\n     ‫العمــارة والهندســة وآخــر مثلــة وصــورة خطــاب مــن احملكمــة لكتابــة‬\n     ‫عــدل ينبــع وصــورة خطــاب أيضــا مــن احملكمــة ينبــع وصــورة صــك‬\n     ‫احلكــم كمــا جــرى منــي اإلطــاع علــى الآلئحــة اإلعتراضيــة املقدمــة‬\n     ‫مــن وكيــل املدعــى عليهــا املقيــدة باحملكمــة برقــم ‪331327268‬‬\n     ‫بتاريــخ ‪1433/7/14‬ه ـ وباإلطــاع عليهمــا فلــم أجــد مــا يؤثــر مــا‬\n     ‫حكمــت بــه وباإلطــاع علــى صــك احلكــم وجــدت أن املدعــي أقــر أنــه‬\n     ‫اســتلم مــن املدعــى عليهــا مبلــغ وقــدره ‪ 770.000‬ســبعمائة وســبعون ألف‬\n     ‫ريــال وانهــا عبــارة عــن قــرض أخذتــه مــن املدعــى عليهــا كمــا وجــدت‬\n     ‫املدعــى عليهــا أقــرت باقتراضهــا مبلــغ ‪ 400.000‬ريــال أربعــة مائــة ألــف‬\n     ‫ريــال مــن املدعــي فجــرى ســؤال املدعــي هــل لديــه بينــة علــى أقراضــه‬\n     ‫املدعــى عليهــا املبلــغ الزائــد عمــا أقــرت بــه وهــو ‪ 370.000‬ريــال فقــال‬\n     ‫ليــس لديــه بينــة علــى ذلــك فجــرى ســؤاله هــل تطلــب ميــن املدعــى عليهــا‬\n     ‫علــى نفــي ذلــك فقــال ال أطلــب ميينهــا لــذا فالزلــت علــى ماحكمــت بــه‬\n     ‫علــى املدعــى عليهــا وحكمــت علــى املدعــي بدفــع مبلــغ ‪ 370.000‬ريــال‬\n     ‫للمدعيــة حــاال وافهمتــه أن لــه ميــن املدعــى عليهــا علــى نفــي دعــواى‬\n     ‫االقــراض يف املبلــغ احملكــوم بــه وبعــرض ذلــك عليــه قــرر عــدم القناعــة‬\n     ‫باحلكــم فجــرى إفاهمــه أنــه ســيتم تســليمه نســخة احلكــم بعــد نهايــة‬\n     ‫اجللســة أن شــاء اهلل وأن عليــه تقــدمي آلئحــة أعتراضيــة خــال ثالثــون‬\n     ‫يومــا تبــدا مــن تاريــخ هــذا اليــوم فأبــدا فهمــه لذلــك وقــرر املدعــى عليهــا‬\n\n\n‫‪79‬‬\n\f‫اإلكتفــاء بالآلئحــة الســابقة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/05‬ه ـ‬\n‫احلمــد هلل وحــدة والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫ففــي يــوم األحــد املوافــق ‪1434/1/11‬ه ـ جــرى منــي االطــاع علــى‬\n‫املعاملــة بعــد ورودهــا مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫برقــم ‪331927096‬وتاريــخ ‪1433/11/17‬ه ـ وقــد صــدر بشــأنها قــرار‬\n‫املالحظــة رقــم ‪33454743‬وتاريــخ ‪1433/11/15‬ه ـ الصــادر مــن‬\n‫الدائــرة احلقوقيــة الثانيــة ونــص احلاجــة منــه وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلتــه‬\n‫ملالحظــة مــا يلــي ‪ -1‬شــهادة البينــة للمدعــي غيــر موصلــة مــن عــدة‬\n‫وجــوه فعلــى فضيلتــه ناظــر القضيــة مراجعــة أقــوال العلمــاء يف ذلــك‬\n‫‪ -2‬إجــراء املقتضــى الشــرعي حيــال بينــة املدعــى عليهــا ‪ -3‬تصحيــح‬\n‫األخطــاء املطبعيــة أ‪ .‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل‬\n‫أنهــم لــم يذكــروا الوجــوه التــي جعلــت البينــة غيــر موصلــة و أمــا بينــة‬\n‫املدعــى عليهــا فهــي غيــر موصلــة ومــا قدمــت هــي شــهادة علــى النفــي وال‬\n‫تخفــى علــى أصحــاب أن املثبــت مقــدم علــى النــايف ويف األصــل الشــهادة‬\n‫علــى النفــي ال تقبــل إال يف مواضــع معلومــة ليــس هــذا منهــا أمــا األخطــاء‬\n‫املطبعيــة فقــد جــرى تصويبهــا علــى الصــك لــذا فــا زلــت علــى مــا‬\n‫حكمــت بــه وقــررت احلــاق مــا جــد علــى صــك احلكــم وســجله وقــررت‬\n‫رفــع املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكــم كاملتبــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                           ‫يف‪1434/1/11‬ه ــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n\n\n                                                                                     ‫‪80‬‬\n\f     ‫يــوم األربعــاء املوافــق ‪ 1434/02/27‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 12.00‬وفيهــا جــرى منــي اإلطــاع علــى املعاملــة بعــد ورودهــا مــن‬\n     ‫محكمــة األســتئناف برقــم ‪ 34261198‬بتاريــخ ‪1434/2/12‬ه ـ وقــد‬\n     ‫صــدر بشــأنها القــرار الصــادر مــن احلقوقيــة الثانيــة ‪ 3431980‬بتاريــخ‬\n     ‫‪1434/2/6‬ه ـ ونــص احلاجــة منــه مــا يلــي وبدراســة الصــك وصــورة‬\n     ‫ضبطــه والئحــة اإلعتراضيــة تقــرر إعادتهــا لفضيلتــه ملالحظــة مــا‬\n     ‫يلــي ‪ -1‬اجــاب فضيلــة القاضــي علــى مــا جــاء بقــرار الدائــرة رقــم‬\n     ‫‪ 33454743‬يف ‪1433/11/15‬ه ـ غيــر مقنــع وال مــاق ملــا طلــب منــه‬\n     ‫‪ -2‬اإلطــاع علــى وكالــة املدعــى عليهــا للمدعــي ورصــد مضمونهــا‬\n     ‫‪ -3‬عمــل املقاصــة بــن املدعــي واملدعــى عليهــا ‪ -4‬التأكــد مــن دعــوى‬\n     ‫القــرض التــي ذكــر املدعــي بأنهــا منظــورة واهلل املوفــق أ‪.‬ه ـ وعليــه‬\n     ‫أجيــب أصحــاب الفضيلــة وفقهــم اهلل أن مــا يخــص املالحظــة األولــى‬\n     ‫بــأن صاحبــي الفضيلــة وفقــه اهلل اجلميــع لــم يبينــا وجــه اإليــراد الــذي‬\n     ‫ذكــراه علــى شــهادة شــهود املدعــي يف قرارهــم الســابق حتــى يتــم‬\n     ‫اجلــواب عليــه وأمــا املالحظــة الثانيــة فبتصفــح املعاملــة وجــدت نســخة‬\n     ‫مــن وكالــة املدعــى عليهــا للمدعــي مرفقــة باملعاملــة لفــة رقــم ‪ 12‬وهــي‬\n     ‫صــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة برقــم ‪ 41304‬وتاريــخ‬\n     ‫‪1428/7/15‬ه ـ وهــذا نــص احلاجــة منهــا بعــد إثبــات حضورهــا‪ :‬وقــررت‬\n     ‫بقولهــا إننــي اقمــت ‪.....‬ســعودي ســجل مدنــي رقــم ‪.....‬وكيــل يف مراجعــة‬\n     ‫الدوائــر احلكوميــة ومحاكــم التمييــز واحملاكــم الشــرعية وديــوان‬\n     ‫املظالــم ووزارة الداخليــة واإلمــارة واحلقــوق املدنيــة والشــرطة واللجــان‬\n     ‫والهيئــات القضائيــة واللجــان العليــا واإلبتدائيــة والتجاريــة والعماليــة‬\n     ‫بكافــة أنواعهــا ومختلــف درجاتهــا ولهــا احلــق املرافعــة واملدافعــة‬\n\n\n‫‪81‬‬\n\f‫وحضــور اجللســات وإقامــة وســماع الدعــاوى واجلــرح والتعديــل واإلقــرار‬\n‫واإلنكار وطلب وتقدمي البيانات وســماع الشــهود واســتجوابهم والطعن‬\n‫فيهــم واإلجابــة واملطالبــة بكافــة حقوقــي لــدا الغيــر وقيمــة العقــارات‬\n‫وفــرز العقــارات واســتالم احلقــوق مبوجــب شــيكات مصرفيــة مصدقــة‬\n‫بأســم وللوكيــل احلــق يف اســتئناف االحــكام ومتييزهــا والقناعــة بهــا‬\n‫واإلعتــراض عليهــا والتظلــم وتعيــن اخلبــراء واحملكمــن والطعــن‬\n‫فيهــم ويف تقاريهــم وطلــب التحكيــم لــدا اي جهــة كانــت وطلــب منــع‬\n‫املعارضــة ورفــع اليــد وإخــاء الســبيل وتقــدمي لوائــح اإلدعــاء والطعــن‬\n‫بالتزويــر والتوقيــع علــى كل مــا يلــزم وكالــة خاصــة فيمــا ذكــر أعــاه‬\n‫ولــه احلــق توكيــل الغيــر وعليــه جــرى التصديــق والتوقيــع حتريــرا يف‬\n‫‪1428/7/15‬ه ـ أ ‪.‬ه ـ وأمــا مــا يخــص املالحظــة الثالثــة أن املقاصــة حــق‬\n‫مــن حقــوق املدعــى عليــه يتــم إجراءهــا بعــد طلبــه وهــو مــا لــم يتــم حســب‬\n‫املــادة الثمانــون مــن نظــام املرافعــات الشــرعية وأمــا مــا يخــص املالحظــة‬\n‫الرابعــة فــأن دعــوى القــرض جــرى املناقشــة املدعــي عنهــا يف اجللســة‬\n‫املنعقــدة يف تاريــخ ‪1433/10/23‬ه ـ وذكــر أنهــا ال أرتبــاط لهــا بهــذه‬\n‫الدعــوى وعلــى أي حــال فمــن حــق املدعــى عليهــا يف حــال وجــود ارتبــاط‬\n‫بــن هــذه وتلــك أن تدفــع لــدا احملكمــة التــي تنظــر دعــوى القــرض بهــذا‬\n‫احلكــم هــذا مــا أحببــت إيضاحــه ألصحــاب الفضيلــة وفقهــم اهلل وال‬\n‫زلــت علــى ماحكمــت بــه وقــررت بعــث املعاملــة حملكمــة االســتئناف‬\n‫كمــا املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/27‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة بينبــع املســاعد الشــيخ ‪.....‬برقــم ‪34651898‬‬\n     ‫وتاريــخ ‪1434/4/16‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلتــه برقــم‬\n     ‫‪ 33303974‬وتاريــخ ‪1433/6/17‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ .....‬ضــد ضــد‬\n     ‫‪ ،.....‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n     ‫باالكثريــة املوافقــة علــى احلكــم بعــد االجــراء االخيــر ‪ .‬واهلل املوفــق‬\n             ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪83‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":65,"source_page_end":83,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c324f5ecf9d1b5542ab6ca16a076896a32458e8b47555b34a8f30de4437b3d5a","normalized_text_hash":"49ed2a6eab1f283a06d439ed7a5aa4e5016bf04ca0ee60f5d9c6e20c9db4a308","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p65-33303974"},{"id":"0bd74c0f-cf5e-5790-88bc-ce4acf622599","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد جعالة -االتفاق بن املدعي وشقيق املدعى عليهم املتوفى على قيام األخير بإجناز عمل معن خال مدة معينة مقابل قيام األول بدفع مقابل ودفع األخير شرط جزائي حال التأخر يف التنفيذ- مطالبة املدعي املدعى عليهم ببيع فلة آلت إليهم عن طريق اإلرث وسداد دين أخيهم املتوفى أو شراء نصيبه ودفع املبلغ له -ال يجوز للجاعل إلزام الطرف اآلخر بشيء حال عدم إمتام العمل -رد","document_number":"3436836","case_number":"33370010","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"عقد جعالة -االتفاق بن املدعي وشقيق املدعى عليهم املتوفى على قيام األخير بإجناز عمل معن خال مدة معينة مقابل قيام األول بدفع مقابل ودفع األخير شرط جزائي حال التأخر يف التنفيذ- مطالبة املدعي املدعى عليهم ببيع فلة آلت إليهم عن طريق اإلرث وسداد دين أخيهم املتوفى أو شراء نصيبه ودفع املبلغ له -ال يجوز للجاعل إلزام الطرف اآلخر بشيء حال عدم إمتام العمل -رد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3436836 :‬تاريخه‪1434/2/13 :‬هـ‬\n                   ‫رقم الدعوى‪33370010 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34210394‬تاريخه‪1434/5/11 :‬هـ‬\n\n\n‫عقــد جعالــة‪ -‬االتفــاق بــن املدعــي وشــقيق املدعــى عليهــم املتوفــى على‬\n‫قيــام األخيــر بإجنــاز عمــل معــن خــال مــدة معينــة مقابــل قيــام األول‬\n‫بدفــع مقابــل ودفــع األخيــر شــرط جزائــي حــال التأخــر يف التنفيــذ‪-‬‬\n‫مطالبــة املدعــي املدعــى عليهــم ببيــع فلــة آلــت إليهــم عــن طريــق اإلرث‬\n‫وســداد ديــن أخيهــم املتوفــى أو شــراء نصيبــه ودفــع املبلــغ لــه‪ -‬ال يجــوز‬\n‫للجاعــل إلــزام الطــرف اآلخــر بشــيء حــال عــدم إمتــام العمــل‪ -‬رد‬\n                                                                     ‫الدعــوى ‪.‬‬\n\n\n\n\n              ‫‪ .1‬قوله تعال ‪ ( :‬وال تأكلوا أموالكم بينكم بالباطل ) ‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (إن دمائكــم وأموالكــم وأعراضكــم حــرام‬\n                                                                 ‫عليكــم ) ‪.‬‬\n      ‫‪ .3‬قاعدة ( األصل يف مال املسلم احلرمة وال يؤخذ إال باحلق ) ‪.‬‬\n\n\n\n\n‫ذكــر املدعــي شــرح ًا لدعــواه أنــه ســبق أن اتفــق مــع أخ املدعــى عليهــم‬\n‫املتوفــى علــى قيامــه باســتخراج صــك حجــة اســتحكام علــى أرض‬\n‫واقعــة باملدينــة املنــورة مقابــل عشــرة باملائــة مــن مســاحة األرض حــال‬\n‫إجنــاز العمــل خــال مــدة معينــة ويف حــال تأخــره عــن اجنــاز ذلــك العمــل‬\n\n                                                                                    ‫‪84‬‬\n\f     ‫يقــوم بدفــع شــرط جزائــي للمدعــي قــدره خمســة وخمســون ألــف ريــال‪.‬‬\n     ‫مت حتريــر ذلــك املبلــغ مبوجــب كمبيــاالت واجبــة الدفــع ‪ ،‬حصــل علــى‬\n     ‫حكــم بذلــك املبلــغ مــن جلنــة الفصــل املنازعــات األوراق التجاريــة إال‬\n     ‫أنــه لــم ينفــذ حتــى اآلن ‪ -‬ذكــر املدعــي أن املدعــى عليهــم حتــت يدهــم‬\n     ‫فيــا آلــت إليهــم إرث ـ ًا ميلــك أخوهــم جــزء ًا فيهــا ولذلــك طلــب إلزامهــم‬\n     ‫ببيــع هــذه الفيــا وســداد حقــه عــن أخيهــم أو شــراء نصيبــه ودفــع املبلــغ‬\n     ‫‪ -‬اعتــرض املدعــى عليهــم علــى ذلــك احلكــم بحجــة أنــه لــم يكتســب‬\n     ‫القطعيــة ‪ -‬مــن كل مــا ســبق ونظــر ًا لكــون العقــد املبــرم بــن الطرفــن‬\n     ‫ســابق الذكــر ال يخلــو أن يكــون إجــارة أو جعالــة وعلــى أيهمــا ال يحــق‬\n     ‫إلــزام الطــرف اآلخــر بشــيء إذا لــم يتــم العمــل وإمنــا يف حالــة عجــزه عــن‬\n     ‫إمتــام العمــل فإنــه ال يســتحق األجــرة أو اجلعــل ملــا يف ذلــك مــن أكل‬\n     ‫أمــوال النــاس بالباطــل وألن األصــل يف مــال املســلم احلرمــة وال يؤخــذ‬\n     ‫منــه إال باحلــق ‪ -‬لــذا فقــد حكمــت احملكمــة بــرد الدعــوى لعــدم ثبــوت‬\n     ‫أحقيــة املدعــي باملبلــغ املطالــب بــه ‪ -‬متــت مصادقــة احلكــم مــن محكمــة‬\n                                                                          ‫اإلســتئناف ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا املــازم القضائــي لــدى فضيلــة الشــيخ‬\n     ‫القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة باملدينة املنورة‪/‬املســاعد‬\n     ‫برقــم ‪ 33370010‬وتاريــخ ‪ 1433/06/01‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 331017491‬وتاريــخ ‪1433/06/01‬ه ـ املتضمــن دعــوى‪ /‬ضــد ‪ /‬ورثــة‬\n     ‫ففــي يــوم األحــد املوافــق‪ 1433/06/29‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n\n‫‪85‬‬\n\f‫‪ 10 :‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫وحضــر حلضــوره مــن الورثــة صاحــب الســجل املدنــي رقــم و صاحــب‬\n‫الســجل املدنــي رقــم الوكيــل عــن مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة عــدل املدينــة الثانيــة رقــم ‪ 33137658‬بتاريــخ ‪1433/06/25‬ه ـ‬\n‫وكمــا وردنــا خطــاب مديــر إدارة املــوارد البشــرية بأمانــة املدينــة رقــم‬\n‫‪ 38048‬وتاريــخ ‪1433/06/10‬ه ـ واملتضمــن مــا نصــه « نفيدكــم بــأن‬\n‫املذكــور مت طــي قيــده بتاريــخ ‪1433/05/12‬هـ لوفاته يرحمه اهلل «أ‪.‬هـ‬\n‫ولــم يتبلــغ بقيــة الورثــة فلذلــك رفعــت اجللســة حملاولــة إبــاغ جميــع الورثــة‬\n‫ويف يــوم األحــد املوافــق‪ 1433/10/15‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة والنصــف وفيهــا حضــر املدعــي واملدعــى عليــه واملدعــى عليــه‬\n‫وكالــة املــدون هويتهــم ســابق ًا ثــم جــرى اإلطــاع علــى صــك إثبــات‬\n‫حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 33266498‬بتاريــخ‬\n‫‪1433/05/25‬ه ـ واملتضمــن « لقــد توفــى أخــي يف ‪1433/05/12‬ه ـ‬\n‫وانحصــر ارثــه يف والدتــه ويف زوجتــه ويف إخوتــه األشــقاء « أ‪.‬ه ـ ثم جرى‬\n‫ســؤال املدعــي عــن دعــواه فلــم يســتطع حتريــر دعــواه وأفهمتــه حتريــر‬\n‫دعــواه كتابي ـ ًا ففهــم ذلــك ويف يــوم الثالثــاء املوافــق ‪1433/12/28‬ه ـ‬\n‫فلــدي أنــا املــازم القضائــي والقائــم بعمــل املكتــب القضائــي الثالــث‬\n‫عشــر حضــر املدعــي أصالــة وحضــر حلضــوره مــن الورثــة املــدون‬\n‫ا عــن كأل مــن أبنــاء وبنــات مبوجــب الوكالــة‬       ‫هويتــه ســابق ًا ووكي ـ ً‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم ‪33153750‬‬\n‫ا عــن مبوجــب‬   ‫يف ‪1433/7/5‬ه ـ وحضــر واملــدون هويتــه ســابق ًا وكي ـ ً‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة برقــم‬\n‫ا ‪ :‬أدعــي علــى‬     ‫‪ 33137658‬يف ‪1433/6/25‬ه ـ وادعــى األول قائ ـ ً‬\n\n\n                                                                                         ‫‪86‬‬\n\f     ‫ورثــة بــأن حتــت يدهــم الفلــة التــي ميلــك جــزء فيهــا املدعــو الصــادر يف‬\n     ‫حقــه صــك رقــم ‪ 7/6/451‬يف ‪1415/7/10‬ه ـ مــن مكتــب الفصــل‬\n     ‫يف املنازعــات التجاريــة بدفــع مبلــغ وقــدره خمســة وخمســن ألــف ريــال‬\n     ‫مقابــل ســندين مســتحق لــي وحيــث أننــي أريــد اســتيفاء حقــي مــن‬\n     ‫املدعــو مــن نصيبيــه يف الفلــة التــي ميلــك نصيــب شــرعي فيهــا أطلــب‬\n     ‫إلــزام املدعــى عليهــم ببيــع الفيــا حتــى أســتويف حقــي مــن املدعــو أو أن‬\n     ‫يشــتروا نصيــب املذكــور وإعطائــي حقــي منــه هــذه دعــواي وبعــرض‬\n     ‫ذلــك علــى وكيــل املدعــى عليهــم قــال ‪ :‬أطلــب مهلــة لإلجابــة عــن هــذه‬\n     ‫الدعــوى ويف يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ لــدي أنــا القاضــي‬\n     ‫املنتــدب للعمــل يف احملكمــة العامــة باملدينــة املنــورة مبوجــب قــرار‬\n     ‫معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 23253‬وتاريــخ ‪1434/1/7‬‬\n     ‫حضــر املدعــي كمــا حضــر املدعــى عليهمــا وكالــة وأصالــة واملــدون‬\n     ‫هويتهــم ووكالــة املدعــى عليــه ســابق ًا وبعــرض مــا مت ضبطــه عليهمــا‬\n     ‫صادقــا عليــه وبطلــب اجلــواب عــن الدعــوى مــن املدعــى عليهــم أجــاب‬\n     ‫املدعــى عليهمــا بقولهمــا مــا ذكــره املدعــي يف دعــواه غيــر صحيــح‬\n     ‫وليــس للمدعــي يف ذمــة ‪ ..‬أي مبلــغ وال يســتحق بيــع الفيــا املذكــورة يف‬\n     ‫دعــواه هكــذا أجابــا وبعــرض ذلــك علــى املدعــي قــال إننــي اتفقــت مــع‬\n     ‫‪...‬علــى أن يقــوم باســتخراج صــك حجــة واســتحكام على ارضــي الواقعة‬\n     ‫يف املدينــة املنــورة علــى طريــق تبــوك مقابــل عشــرة باملائــة مــن مســاحة‬\n     ‫األرض يف حــال أجنــز العمــل خــال خمســة أشــهر ويف حــال تأخــره ولــم‬\n     ‫يقــم بإجنــاز العمــل فإنــه قــد نــص يف العقــد علــى شــرط جزائــي بحيــث‬\n     ‫يدفــع لــي مبلــغ وقــدره خمســة وخمســون ألــف ريــال وهــي التــي أطالــب‬\n     ‫بهــا فجــرى ســؤاله كيــف صــدر فيهــا حكــم مــن جلنــة الفصــل يف‬\n\n\n‫‪87‬‬\n\f‫املنازعــات علــى األوراق التجاريــة فقــال إنــه أصــدر كمبيــاالت لــي بهــا‬\n‫وصــدر حكــم لــي بهــذا النــزاع واطلــب مهلــة إلحضارهــا فأجيــب لطلبــه‬\n‫ويف يــوم األربعــاء املوافــق ‪ 1434/01/28‬ه ـ حضــر املدعي كما حضر‬\n‫املدعــى عليهمــا وكالــة كمــا حضــر ‪ ...‬الســعودي بالســجل املدنــي رقــم‬\n‫وبطلــب الصكــوك التــي وعــد املدعــي بإحضارهــا أبــرز الصــك رقــم‬\n‫‪ 16/200/81‬وتاريــخ ‪1429/7/4‬ه ـ الصــادر مــن فضيلــة القاضــي يف‬\n‫احملكمــة العامــة باملدينــة املنــورة واملنقــوض مــن محكمــة التمييــز‬\n‫مبكــة املكرمــة بالقــرار الصــادر مــن الدائــرة احلقوقيــة السادســة رقــم‬\n‫‪/6/1‬ن وتاريــخ ‪1430/1/8‬ه ـ كمــا أبــرز الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 33129032‬وتاريــخ‬\n‫‪1433/3/13‬ه ـ حيــث أقــام دعــوى إعســار يف مواجهــة املدعــي يف هــذه‬\n‫الدعــوى ولــم يوافــق املدعــى عليــه علــى اإلعســار وطلــب بيــع نصيــب‬\n‫مدعــي اإلعســار يف عقــار والــده وقــد أفهمــه فضيلــة ناظــر الدعــوى‬\n‫بإقامــة الدعــوى علــى الورثــة وســؤال املدعــي عــن املبلــغ الــذي يطالــب بــه‬\n‫قــال إنــه خمســمائة وخمســون ألــف ريــال وســؤاله عــن احلكــم الصــادر‬\n‫لــه بهــذا املبلــغ الــذي يطلــب بيــع العقــار ألجلــه فأبــرز القــرار الصــادر مــن‬\n‫مكتــب الفصــل يف نزاعــات األوراق التجاريــة باملدينــة برقــم ‪28/98‬‬\n‫وتاريــخ ‪1428/2/1‬ه ـ املتضمــن إلــزام بدفــع مبلــغ خمســمائة وخمســن‬\n‫ألــف ريــال وبعرضــه علــى املدعــى عليهــم قالــوا إن القــرار لــم يكتســب‬\n‫القطعيــة وقــد أعتــرض علــى القــرار وســلم االعتــراض لــوزارة التجــارة‬\n‫يــوم أمــس ثــم قــرر املدعــى عليــه قائــا إننــي اتفقــت مــع املدعــي علــى‬\n‫أن أقــوم باســتخراج صــك حجــة اســتحكام خــال ثالثــة أشــهر ألرض‬\n‫تقــع علــى طريــق تبــوك تبلــغ مســاحتها مائتــي ألــف متــر مربــع ثــم زادت‬\n\n\n                                                                                           ‫‪88‬‬\n\f     ‫حتــى بلغــت مليونــي متــر مربــع علــى أن يســلمني املدعــي األوراق التــي‬\n     ‫تخــص األرض ووكالــة ويف حــال عــدم وفائــي بذلــك أدفــع لــه مبلــغ‬\n     ‫خمســمائة وخمســن ألــف ريــال وبعــد االتفــاق أخــذ املدعــي يتهــرب مــن‬\n     ‫تســليمي الوثائــق والوكالــة ومــرة أتصــل بــه ويقــول أنــا يف جــدة ومــرة‬\n     ‫أخــرى يف تبــوك وهكــذا حتــى انتهــت املــدة هكــذا قــال وبعــرض ذلــك‬\n     ‫علــى املدعــي قــال بــل ســلمته وكالــة بعــد االتفــاق بثالثــة أيــام تقريبــا‬\n     ‫فطلبــت منــه رقــم الوكالــة وتاريخهــا فقــال أحضــره يف اجللســة القادمــة‬\n     ‫لــذا قــررت الكتابــة ملكتــب الفصــل يف منازعــات األوراق التجاريــة‬\n     ‫باملدينــة لإلفــادة عمــا ذكــره املدعــى عليهــم مــن عــدم اكتســاب قــرار‬\n     ‫وزارة التجــارة للقطعيــة وحتــى ورود اجلــواب رفعــت اجللســة ويف يــوم‬\n     ‫الثالثــاء املوافــق ‪1434/2/12‬ه ـ فتحــت اجللســة وفيهــا حضــر املدعــى‬\n     ‫عليهــم ولــم يحضــر املدعــي ووجــدت يف املعاملــة كتابـ ًا بتوقيــع منســوب‬\n     ‫للمدعــي يعتــذر فيــه عــن احلضــور ولــم يقيــد يف احملكمــة لــذا قــررت‬\n     ‫عــدم قبــول العــذر والســير يف الدعــوى وكنــت قــد كتبــت كتابــي رقــم‬\n     ‫‪ 34/283522‬وتاريــخ ‪1434/2/4‬ه ـ املوجــه ملديــر فــرع وزارة التجــارة‬\n     ‫باملدينــة املنــورة والــذي أطلــب فيــه اإلفــادة عــن احلكــم الصــادر ضــد‬\n     ‫‪ /‬برقــم ‪ 82/98‬وتاريــخ ‪1428/2/1‬ه ـ وقــد وردنــي اجلــواب بالكتــاب‬\n     ‫رقــم ‪/239‬ف‪/‬م‪/‬ق وتاريــخ ‪1434/2/11‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 34/356648‬وتاريــخ ‪1434/2/12‬ه ـ ونــص احلاجــة منــه مــا يلــي (‬\n     ‫نفيــد فضيلتكــم بأنــه تقــدم وكيــل املدعــى عليــه بالئحــة اعتــراض‬\n     ‫علــى قــرار مكتــب الفصــل وبعــث للجنــة القانونيــة برقــم ‪/266‬ف‪/‬م‪/‬ق‬\n     ‫وتاريــخ ‪1434/2/6‬ه ـ وحتــى تاريخــه لــم تــرد النتيجــة علمـ ًا بــأن قــرارات‬\n     ‫مكتب الفصل مشــمولة بالنفاذ املعجل بغير كفالة أ‪.‬هـ وبعد االطالع‬\n\n\n‫‪89‬‬\n\f‫علــى ضبــط الدعــوى واجلــواب ونظــر ًا لكــون العقــد املبــرم بــن الطرفــن‬\n‫ال يخلــو إمــا أن يكــون إجــارة أو جعالــة وعلــى أيهمــا ال يحــق للمؤجــر‬\n‫وال للجاعــل إلــزام الطــرف األخــر بشــيء إذا لــم يتــم العمــل وإمنــا يف حــال‬\n‫عجــزه عــن إمتــام العمــل فإنــه ال يســتحق األجــرة أو اجلعــل وملــا يف اشــتراط‬\n‫مثــل ذلــك مــن أكل أمــوال النــاس بالباطــل وقــد نهــى اهلل عــز وجــل عــن‬\n‫ذلــك بقولــه ( وال تأكلــوا أموالكــم بينكــم بالباطــل ) وألن األصــل‬\n‫يف مــال املســلم احلرمــة وال يأخــذ إال باحلــق قــال صلــى اهلل عليــه وســلم‬\n‫يف خطبتــه يف حجــة الــوداع (إن دمائكــم وأموالكــم وأعراضكــم‬\n‫حــرام عليكــم ) لــكل مــا ســبق فقــد ثبــت لــدي عــدم أحقيــة املدعــي‬\n‫باملبلــغ الــذي يطالــب بــه وحكمــت بــرد دعــواه وأخليــت ســبيل املدعــى‬\n‫عليهــم منهــا هــذا مــا ظهــر لــي وبــه حكمــت واهلل اعلــم واحكــم ويعتبــر‬\n‫احلكــم يف حــق املدعــي حضوريـ ًا وقــررت بعــث نســخة مــن صــك احلكــم‬\n‫للمدعــي لتقــدمي اعتراضــه عليــه خــال ثالثــن يوم ـ ًا ابتــدأ مــن تاريــخ‬\n‫هــذا اليــوم إن قــدم اعتراضــه خاللهــا وإال ســقط حقــه يف االعتــراض يف‬\n‫االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/12‬هـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا املــازم القضائــي القائــم بعمــل‬\n‫فضيلــة القاضــي يف احملكمــة العامــة باملدينــة املنــورة ويف يــوم األربعــاء‬\n‫‪1434/06/07‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف برقــم ‪ 331017491‬يف ‪1434/5/18‬ه ـ‬\n‫وبرفقهــا صــك احلكــم رقــم ‪ 3436836‬وتاريــخ ‪1434/2/13‬ه ـ واملظهــر‬\n‫عليــه بقــرار أصحــاب الفضيلــة قضــاة االســتئناف رقــم ‪34210394‬‬\n‫وتاريــخ ‪1434/5/11‬ه ـ املتضمــن املوافقــة علــى احلكــم باألكثريــة‬\n\n\n                                                                                       ‫‪90‬‬\n\f     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪ 1434/06/07‬ه ـ‬\n     ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ - :‬فق ــد ج ــرى‬\n     ‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n     ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n     ‫الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمة العامــة باملدينة املنورة‬\n     ‫واملسجل بع ــدد ‪ 3436836‬وتاريخ ‪1434/2/13‬ه ـ املتضمن دعوى ضد‬\n     ‫ورثــة احملكــوم في ــه مبــا دون باطــن الصــك‪ ،‬وبدراس ــة احلكــم وص ــورة‬\n     ‫ضبط ــه و الئحته االعتراضية تق ــرر باألكثرية املوافق ــة عل ــى احلكم‪،‬‬\n      ‫واهلل املوفــق‪ .‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪91‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":84,"source_page_end":91,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b85e4ba9ac36915cbfe283d629e3a78e1c1652bd026ff4a7a937fd4d5c6957c5","normalized_text_hash":"ad1ae576c186602c105745ad9a0bfdfbc9d985750eb9940d2c8e80e8de016aa9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p84-3436836"},{"id":"96a1bbb3-9a3b-5b4b-ac2e-84b424025024","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بأتعاب محاماة -رد الشهادة إذا جرت نفع ا أو دفعت ضرر ا عن الشاهد -احلكم بالشاهد واليمن.","document_number":"3423919","case_number":"3471898","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/12","year":"1434","subject":"مطالبة بأتعاب محاماة -رد الشهادة إذا جرت نفع ا أو دفعت ضرر ا عن الشاهد -احلكم بالشاهد واليمن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3423919:‬تاريخه‪1434/6/12:‬هـ‬\n                    ‫رقم الدعوى‪3471898:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34297254‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n‫مطالبــة بأتعــاب محامــاة ‪ -‬رد الشــهادة إذا جــرت نفع ـ ًا أو دفعــت ضــرر ًا‬\n                                  ‫عــن الشــاهد ‪ -‬احلكــم بالشــاهد واليمــن‪.‬‬\n\n\n\n\n‫حديــث ابــن عبــاس رضــي اهلل عنــه (أن النبــي صلــى اهلل عليــه وســلم‬\n                                ‫قضــى بشــاهد وميــن) أخرجــه مســلم‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اتفــق معــه للترافــع عنــه ضــد أحــد‬\n‫األشــخاص مبطالبتــه مببلــغ أربعمائــة ألــف ريــال وذلــك مقابــل ‪ %20‬مــن‬\n‫املبلــغ احملكــوم بــه وقــد قــام بالترافــع عنــه وحكــم لصالــح املدعــى‬\n‫عليــه مببلــغ ثالثمائــة وثمانيــة وخمســن ألــف ريــال ولــم يســلمه املدعــى‬\n‫عليــه منهــا شــيئ ًا ويطلــب إلزامــه بتســليمه مبلــغ وقــدره واحــد وســبعون‬\n‫ألف ـ ًا وســتمائة ريــال هكــذا ادعــى ‪ -‬أجــاب املدعــى عليــه باملصادقــة‬\n‫علــى الدعــوى عــدا قولــه أن االتفــاق علــى املبلــغ احملكــوم بــه والصحيــح‬\n‫أنــه علــى املبلــغ احملصــل مــن احملكــوم عليــه وأن املدعــي لــم يقــم‬\n‫بتحصيــل أي مبلــغ ‪ -‬أحضــر املدعــى عليــه بينــة وهمــا شــاهدان شــهدا‬\n‫طبــق جوابــه ودفعــه ‪ -‬طعــن املدعــي بأحــد الشــهود بــأن لــه عقــد مطالبــة‬\n‫مماثــل لعقــد املدعــى عليــه معــه ضــد نفــس املدعــو وأن شــهادته جتــر لــه‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫نفعـ ًا ‪ -‬صــادق الشــاهد علــى طعــن املدعــي ‪ -‬حلــف املدعــى عليــه اليمــن‬\n     ‫تكملــة لبينتــه ‪ -‬حيــث أن النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد‬\n     ‫وميــن أخرجــه مســلم ‪ -‬صــدر احلكــم بإثبــات عــدم اســتحقاق املدعــي‬\n     ‫ملــا يدعيــه بالصفــة التــي ذكرهــا يف دعــواه ‪ -‬اعتــرض املدعــي بالئحــة‬\n     ‫‪ -‬صــدق احلكــم مــن الدائــرة الثانيــة مبحكمــة االســتئناف باملنطقــة‬\n                                                                      ‫الشــرقية ‪.‬‬\n\n\n\n\n     ‫العامــة‬\n        ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫العامــة مبحافظــة القطيــف برقــم ‪ 3471898‬وتاريــخ‬   ‫َ‬     ‫رئيــس احملكمــة‬\n     ‫‪ 1434/02/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34361654‬وتاريــخ‬\n     ‫‪ 1434/02/12‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/05/08‬هـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي ‪ ........‬يحمــل الســجل‬\n     ‫املدنــي رقــم ‪ ........‬علــى احلاضــر معــه ‪ ........‬يحمــل الســجل املدنــي رقــم‬\n     ‫‪ ........‬يف دعــواه لقــد اتفقــت مــع املدعــى عليــه علــى الترافــع وكالــة‬\n     ‫عنــه ضــد املدعــو ‪ ........‬مبطالبتــه مببلــغ أربعمائــة ألــف (‪)400000‬ريــال‬\n     ‫وذلــك مقابــل عــوض قــدره عشــرون باملائــة (‪ )20%‬مــن املبلــغ احملكــوم‬\n     ‫بــه وقــد قمــت بالترافــع عنــه وحكــم لصالــح املدعــى عليــه أصالــة مببلــغ‬\n     ‫قــدره ثالثمائــة وثمانيــة وخمســون ألــف (‪ )358000‬ريــال مبوجــب صــك‬\n     ‫احلكــم الصــادر مــن ســلفكم بهــذه احملكمــة فضيلــة الشــيخ ‪........‬‬\n     ‫برقــم ‪ 6/9‬يف ‪1429/02/04‬ه ـ وبالتالــي أصبــح املســتحق لــي بذمــة‬\n     ‫املدعــى عليــه مبلغ ـ ًا وقــدره واحــد وســبعون ألف ـ ًا وســتمائة (‪)71600‬‬\n\n‫‪93‬‬\n\f‫ريــال لــم يســلمني منهــا شــيئ ًا لــذا أطلــب احلكــم بالزامــه بتســليمي مبلــغ‬\n‫واحــد وســبعني ألف ـ ًا وســتمائة (‪)71600‬ريــال هــذه دعــواي وبعرضهــا‬\n‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي كلــه صحيــح عــدا قولــه ان‬\n‫االتفــاق كان علــى املبلــغ احملكــوم بــه فغيــر صحيــح والصحيــح أننــي‬\n‫اتفقــت معــه علــى نســبة عشــرين باملائــة (‪ )20%‬مــن كل مبلــغ يحصلــه‬\n‫املدعــي أصالــة مــن‪ ........‬وليــس مــن املبلــغ احملكــوم بــه واملدعــي لــم‬\n‫يحصــل لــي أي مبلــغ مــن املذكــور حتــى اآلن فعليــه فمتــى مــا ســلمني‬\n‫املدعــي أي مبلــغ مــن احملكــوم عليــه ‪ ........‬فلــه عشــرون باملائــة منــه‬\n‫وأمــا اآلن فــا حــق لــه جتاهــي هكــذا أجــاب وبعرضــه علــى املدعــي‬\n‫قــال بــل الصحيــح مــا ذكرتــه هكــذا قــرر فســألت املدعــي هــل اســتلم‬\n‫املدعــى عليــه أي مبلــغ مــن املبلــغ املســتحق لــه بذمــة املدعــو ‪ ........‬فقــال‬\n‫ال علــم بذلــك وال عالقــة هكــذا قــرر ثــم قــرر املدعــى عليــه بقولــه‬\n‫لــدي البينــة علــى أن االتفــاق كان بالنســبة للمبلــغ احملصــل واملســتلم‬\n‫وليــس للمحكــوم بــه وأطلــب ســماعها هكــذا قــرر وبعــد االذن لــه قــدم‬\n‫احلاضــر معــه ‪ ........‬يحمــل الســجل املدنــي رقــم ‪ ........‬وبســؤاله عن عمره‬\n‫قــال إنــه مــن مواليــد عــام ‪1394‬ه ـ وعــن عملــه قــال ‪ ...‬وعــن ســكنه قــال‬\n‫‪ ...‬وعــن جهــة اتصالــه باملتداعيــن قــال اجنبــي عنهمــا وتربطنــي بهمــا‬\n‫مجــرد صداقــة هكــذا قــرر كمــا قــدم احلاضــر معــه ‪ ........‬يحمــل‬\n‫الســجل املدنــي رقــم ‪ ........‬وبســؤاله عــن عمــره قــال إننــي مــن مواليــد‬\n‫عــام ‪1397‬ه ـ وبســؤاله عــن عملــه قــال متســبب وعــن ســكنه قــال ‪........‬‬\n‫وعــن جهــة اتصالــه باملتداعيــن قــال أجنبــي عنهمــا وال تربطنــي بهمــا‬\n‫ســوى مجــرد صداقــة وبســؤال كل واحــد منهمــا منفــردا عمــا لديــه‬\n‫مــن شــهادة قــرر قائــا أشــهد هلل تعالــى أننــي اجتمعــت مــع املتداعيــن‬\n\n\n                                                                                         ‫‪94‬‬\n\f     ‫بخصــوص مطالبــة ‪ ...‬مببلــغ وســمعتهما يتفقــان علــى أن يطالــب املدعــي‬\n     ‫عــن املدعــى عليــه املدعــو‪ ........‬مببلــغ أربعمائــة ألــف ريــال وكان‬\n     ‫اتفاقهمــا علــى أن يســتحق املدعــي عوضــا قــدره عشــرون باملائــة مــن‬\n     ‫ـدي وبــه أشــهد وبعرضهــا علــى املدعــي‬ ‫املبلــغ احملصــل واملســتلم هــذا مــا لـ َّ‬\n     ‫أصالــة قــال مــا جــاء يف شــهادتهما غيــر صحيــح وأمــا عدالتهمــا فــا أعلم‬\n     ‫عنهمــا شــيئ ًا كمــا أن الشــاهد ‪ ...‬لــه عقــد مطالبــة مماثــل معــي لعقــد‬\n     ‫املدعــى عليــه ضــد نفــس املدعــو ‪ ........‬فشــهادته جتــر لــه منفعــة هكــذا‬\n     ‫قــرر فجــرى ســؤال الشــاهد ‪ ....‬عمــا قــرره املدعــي حيالــه فقــال صحيــح‬\n     ‫إن لــي عقــد مماثــل مــع املدعــي ضــد ‪ ........‬وكان اتفاقــي مــع املدعــي‬\n     ‫بنفــس املجلــس الــذي اتفــق فيــه املدعــي مــع املدعــى عليــه هكــذا قــرر‬\n     ‫ثــم قــال املدعــي أطلــب توجيــه بعــض األســئلة إلــى الشــاهد ‪ ....‬هكــذا‬\n     ‫قــرر ثــم حضــر الشــاهد ‪ ....‬وبســؤال املدعــي عــن مالديــه مــن أســئلة يريــد‬\n     ‫توجيههــا للشــاهد فقــال أطلــب التأكيــد بســؤال الشــاهد هــل كان‬\n     ‫حاضــرا وقــت االتفــاق بينــي وبــن املدعــى عليــه هكــذا قــرر وبعرضــه‬\n     ‫علــى الشــاهد قــال نعــم كنــت حاضــرا هكــذا قــرر ثــم قــال املدعــي‬\n     ‫‪ :‬إن الشــاهد لــه مطالبــة بحــق ‪ ........‬وكان يريــد توكيلــي ولكنــه‬\n     ‫ســألني بأحــد األيــام عــن النســبة التــي اتفقــت فيهــا مــع املدعــى عليــه ولــو‬\n     ‫كان حاضــرا ملــا ســألني عــن النســبة هكــذا قــرر وبســؤال الشــاهد‬\n     ‫هــل ســأل املدعــي عــن النســبة التــي اتفــق فيهــا مــع املدعــى عليــه فقــال‬\n     ‫ال هكــذا قــرر ثــم ســألت املدعــى عليــه هــل لديــك زيــادة بينــة فقــال‬\n     ‫ال هكــذا قــرر ثــم ســالت املدعــي هــل لديــك بينــة علــى صحــة دعــواك‬\n     ‫فقــال البينــة لــدي هكــذا قــرر وبســؤال املدعــى عليــه تعديــل شــاهده ‪....‬‬\n     ‫قــدم احلاضريــن معــه‪ ........ ........‬ســجل مدنــي رقــم ‪ ........‬و‪ ........‬ســجل‬\n\n\n‫‪95‬‬\n\f‫مدنــي رقــم ‪ ........‬وقــد شــهد كل واحــد منهمــا بعدالــة وثقــة الشــاهد‬\n‫‪ ........‬بقولهمــا ان الشــاهد ‪ ........‬ثقــة عــدل مرضــي الشــهادة هكــذا‬\n‫شــهدا ثــم افهمــت املدعــى عليــه أن عليــه اليمــن تكملــة للشــاهد الــذي‬\n‫ال‬‫قدمــه فاســتعد ببــذل اليمــن ثــم حلــف بعــد تخويفــه بــاهلل واالذن له قائ ً‬\n‫واهلل العظيــم أن اتفاقــي مــع املدعــي يف املطالبــة باملبلــغ املســتحق لــي‬\n‫بذمــة ‪ ........‬كان بنســبة عشــرين باملائــة مــن كل مبلــغ يقــوم بتحصيلــه‬\n‫لــي وليــس مــن املبلــغ احملكــوم لــي بــه واهلل العظيــم هكــذا حلــف ثــم‬\n‫قفلــت املرافعــة وبعــد ســماع الدعــوى وجوابهــا وحيــث صــادق املدعــى‬\n‫عليــه علــى أصــل االتفــاق املدعــى بــه وأنكــر اســتحقاق املدعــي ألتعابــه‬\n‫مبجــرد احلكــم علــى املديــن ‪ ........‬وقــرر أن االتفــاق علــى أن يســتحق‬\n‫املدعــي نســبة عشــرين باملائــة مــن كل مبلــغ يحصلــه املدعــي مــن ‪........‬‬\n‫ومبــا أن الشــاهد‪ ........‬الــذي قدمــة املدعــى عليــه لــه اتفــاق مماثــل مــع‬\n‫املدعــي ممــا يجعــل شــهادته مظنــة دفــع ضــرر عنــه ممــا يــرد شــهادته‬\n‫وحيــث ان الشــاهد ‪ ...‬شــهد بصحــة مــا قــرره املدعــى عليــه ومت تعديلــه‬\n‫شــرع ًا وحيــث حلــف املدعــى عليــه تكملــة للشــاهد الــذي قدمــه وقــد‬\n‫قضــى صلــى اهلل عليــه وســلم بالشــاهد واليمــن كمــا يف حديــث ابــن‬\n‫عبــاس رضــي اهلل عنهمــا يف صحيــح مســلم وحيــث قــرر املدعــي أال بينــة‬\n‫لديــه فقــد ثبــت لــدي عــدم اســتحقاق املدعــي ملــا يدعيــه بالصفــة التــي‬\n‫ذكرهــا يف دعــواه وبــه حكمــت وبعرضــه لــم يقنــع بــه املدعــي طالب ـ ًا‬\n‫متييــزه فأفهــم باملراجعــة يــوم االربعــاء املوافــق ‪1434/06/14‬ه ـ الســتالم‬\n‫نســخة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا مــن تاريــخ‬\n‫اســتالمه نســخة احلكــم وبعــد انتهاءهــا دون تقــدمي اعتراضــه يســقط‬\n‫حقــه فيــه ويكتســب احلكــم القطعيــه ففهــم ذلــك واســتعد بــه وبــاهلل‬\n\n\n                                                                                     ‫‪96‬‬\n\f     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/06/12‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم ‪ 341787242‬وتاريــخ ‪ 1434/ 7/24‬ه ـ‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم‬\n     ‫‪ 34361654‬وتاريــخ ‪1434/7/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ......../‬املســجل برقــم ‪34239195‬‬\n     ‫وتاريــخ ‪1434/6/12‬ه ـ بشــأن دعــوى‪ ......../‬ضــد‪ ......../‬يف قضيــة‬\n     ‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلــة القاضــي مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/8/14‬ه ـ ‪.‬‬\n\n\n\n\n‫‪97‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":92,"source_page_end":97,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5d283670514b6d691a0569b2d565447ee197eaba4ec6e41170d0b83b8dc1e720","normalized_text_hash":"fef435cad5874e8695c327d409b9d8b4d41dafdc14f18bb1727e87bbb7b82ca4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p92-3423919"},{"id":"5cdbb3c6-e7d6-5708-befd-96355c8154ce","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -مطالبة بأجرة محاماة -تخلف عن حضور اجللسة -قيام البينة على الدعوى -إلزام املدعى عليه بدفع األجرة.","document_number":"33173378","case_number":"32187422","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/5","year":"1434","subject":"أتعاب -مطالبة بأجرة محاماة -تخلف عن حضور اجللسة -قيام البينة على الدعوى -إلزام املدعى عليه بدفع األجرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33173378 :‬تاريخه‪1433/4/5 :‬هـ‬\n                   ‫رقم الدعوى‪32187422 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3445201‬تاريخه‪1434/2/24 :‬هـ‬\n\n\n‫أتعــاب ‪ -‬مطالبــة بأجــرة محامــاة ‪ -‬تخلــف عــن حضــور اجللســة ‪ -‬قيــام‬\n                ‫البينــة علــى الدعــوى ‪ -‬إلــزام املدعــى عليــه بدفــع األجــرة‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قوله تعالى‪»:‬يا أيها الذين آمنوا أوفوا بالعقود»‪.‬‬\n             ‫‪ -2‬قوله صلى اهلل عليه وسلم‪ « :‬املسلمون على شروطهم»‪.‬‬\n\n\n\n\n‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه أبــرم معــه عقــد محامــاة‬\n‫يتولــى مبوجبــه املرافعــة واملدافعــة يف القضايــا املتعلقــة بــه بثمــن معلــوم‬\n‫محــدد وقــد قــام بالعمــل علــى الوجــه املطلــوب إال أنــه لــم يســلم لــه إال‬\n‫بعــض املبلــغ املتفــق عليــه ويطلــب احلكــم عليــه بدفــع الباقــي ‪ -‬بعرضــه‬\n‫علــى املدعــى عليــه طلــب إمهالــه جللســة قادمــة إلحضــار جــواب ‪ -‬لــم‬\n‫يحضــر املدعــى عليــه يف اجللســة املقــررة لــذا فقــد طلبــت الدائــرة مــن‬\n‫املدعــي البينــة فأبــرز وثيقــة اتفــاق تتضمــن إقــرار املدعــى عليــه بإبرامــه‬\n‫عقــد محامــاة مــع املدعــي وقــدر الواصــل منــه واملتبقــي وتاريــخ تســليمه‬\n‫كمــا أبــرز نســخة حكــم صــادرة مــن ديــوان املظالــم مضمونهــا إثبــات‬\n‫الصلــح بــن الطرفــن يف الدعــوى املتفــق عليهــا ‪ -‬بنــاء علــى مــا تقــدم‬\n‫مــن دعــوى املدعــي ولعــدم حضــور املدعــى عليــه مــع تبلغــه وملــا ورد يف‬\n\n                                                                                      ‫‪98‬‬\n\f     ‫العقــد احملــرر بــن الطرفــن واملرصــود نصــه أعــاه ولكــون املدعــي قــد‬\n     ‫أجنــز مــا أوكل إليــه وذلــك ثابــت باحلكــم الصــادر مــن ديــوان املظالــم‬\n     ‫ولقولــه تعالــى «‪:‬يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود «‪ ،‬ولقولــه صلــى اهلل‬\n     ‫عليــه وســلم «املســلمون علــى شــروطهم»‪ ،‬ولكــون املدعــى عليــه ســلم‬\n     ‫جــزء مــن املبلــغ املتفــق عليــه وبقــي املبلــغ املدعــى بــه وقــدره أربعــون ألــف‬\n     ‫ريــال لــكل مــا تقــدم حكمــت الدائــرة علــى املدعــى عليــه الغائــب عــن‬\n     ‫مجلــس احلكــم بدفــع أربعــن ألــف ريــال لصالــح املدعــي أصالــة وقــررت‬\n     ‫بعــث صــورة مــن صــك احلكــم لــه وإفهامــه بتعليمــات االعتــراض ‪ -‬قــدم‬\n     ‫املدعــى عليــه الئحتــه االعتراضيــة ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                               ‫االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n     ‫جدة‪/‬املســاعد برقــم ‪ 32187422‬وتاريــخ ‪ 1432/05/21‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32585931‬وتاريــخ ‪ 1432/05/21‬ه ـ ففــي يــوم‬\n     ‫االثنــن املوافــق‪ 1432/11/05‬ه ـ أفتتحــت اجللســة الســاعة ‪11 : 00‬ص‬\n     ‫وفيهــا حضــر املدعــي أصالــة ‪ ..............‬ســجل مدنــي رقــم……………‬\n     ‫واملدعــى عليــه وكالــه ‪ ................‬ســجل مدنــي رقــم ……………‬\n     ‫بوكالتــه عــن ‪ ....................‬مبوجــب وكالــة رقــم ‪ 28352‬وتاريــخ‬\n     ‫‪1432/8/11‬ه ـ جلــد ‪ 3472‬والصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بجنــوب جــدة والتــي تخولــه حضــور اجللســات واإلجابــة عــن موكلــه‬\n\n‫‪99‬‬\n\f‫املذكــور وادعــى املدعــي قائــا‪ -:‬ادعــي أنــا ‪ .............‬بالوكالــة عــن‬\n‫شــركة ‪ ..........‬و‪ ..............‬علــى احلاضــر معــي باملجلــس ‪ .........‬قائــا يف‬\n‫تقريــر دعــواي‪ :‬لقــد ابــرم املدعــى عليــه مــع موكلــي عقــد احملامــاة رقــم‬\n‫‪ 116‬واملــؤرخ يف ‪1430/2/24‬ه ـ املوافــق ‪2009/2/19‬م يتولــى مبوجبــه‬\n‫موكلتــي القيــام مبهمــة املرافعــة واملدافعــة يف القضايــا املتعلقــة باملدعــى‬\n‫عليــه مقابــل أتعــاب متفــق عليهــا تقــدر ب ـ (‪ ) 105000‬مائــة وخمســة آالف‬\n‫ريــال وحيــث أن موكلتــي قــد أمتــت كافــة املطلــوب منهــا علــى أكمــل‬\n‫وجــه ولكــن املدعــى عليــه لــم يقــم بســداد األتعــاب املتفــق عليهــا بينهــم‬\n‫ســوى مبلــغ وقــدره (‪ )65000‬خمســة وســتون ألــف ريــال ولذلــك يكــون‬\n‫بذمــة املدعــى عليــه مبلــغ وقــدره (‪)40000‬أربعــون ألــف ريــال مســتحقه‬\n‫وواجبــه الدفــع ملوكلتــي منــذ تاريــخ ‪2010/3/30‬م مبوجــب محضــر‬\n‫اإلنفــاق املبــرم بــن الطرفــن واملــؤرخ يف ‪1430/12/30‬ه ـ املوافــق‬\n‫‪2009/12/17‬م ملــا ســبق ذكــره اطلــب مــن فضيلتكــم احلكــم بإلــزام‬\n‫املدعــى عليــه بســداد مبلــغ وقــدره (‪)40000‬أربعــون ألــف ريــال متثــل‬\n‫املتبقــي مــن اســتحقاق موكلتــي ضــد املدعــى عليــه‪ .‬هكــذا أدعــى‪.‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن الدعــوى أجــاب قائــا اطلــب تســليمي‬\n‫صــورة مــن صحيفــة الدعــوى ومرفقاتهــا لكــي أمتكــن مــن الرجــوع إلــى‬\n‫موكلــي وإعــداد ردي علــى الدعــوى هكــذا أجــاب وعليه جرى تســليمه‬\n‫صــورة مــن صحيفــة الدعــوى ومرفقاتهــا والعقــد احملــرر بــن الطرفني يف‬\n‫‪1430/02/24‬هـ ـ ومحضــر االتفــاق املؤرخ يف ‪1430/12/30‬ه ـ ورفعت‬\n‫اجللســة ويف جلســة أخــرى وفيهــا حضــر املدعــي أصالــة ‪..................‬‬\n‫ســجل مدنــي رقــم ‪ ................‬ولــم يحضــر املدعــى عليــه أو مــن ميثلــه مــع‬\n‫تبلغهــم للجلســة واســتمهالهم إلحضــار اإلجابــة ولــم يتقــدم بعــذر لعــدم‬\n\n\n                                                                                        ‫‪100‬‬\n\f      ‫حضــوره عليــه قــررت ســماع مالــدي املدعــي مــن بينــة علــى دعــواه فابــرز‬\n      ‫مــن يــده صــورة عقــد مكونــة مــن ورقتــن جــرى إرفــاق صــورة منهــا‬\n      ‫باملعاملــة ونصهــا مايلــي» إنــه يف يــوم اخلميــس ‪1430/12/30‬ه ـ املوافــق‬\n      ‫ال مــن ‪ -1 :‬شــركة ‪....................‬‬\n                                             ‫‪2009/12/17‬م مت االتفــاق بــن ك ً‬\n      ‫و‪ ................‬محامــون ومستشــارون قانونيــون وميثلهــا احملامــي واملستشــار‬\n      ‫القانونــي ‪( ...............‬طــرف أول)‪ -2 .‬الســيد‪ ................ -‬أصالــة عــن‬\n      ‫ا عــن زوجتــه ‪ .........‬بصفتهــم الشــركاء يف‬       ‫نفســه وبصفتــه وكي ـ ً‬\n      ‫شــركة مصنــع ‪ ...............‬لتكريــر الزيــوت (طــرف ثاني)‪.‬حيــث أن‬\n      ‫الطــرف الثانــي قــد أبــرم مــع الطــرف األول عقــد محامــاة بتاريــخ اخلميس‬\n      ‫‪1430/02/24‬ه ـ املوافــق ‪2009/02/19‬م يقــوم مبقتضاه الطرف األول‬\n      ‫باملرافعــة واملدافعــة عــن الطــرف الثانــي يف القضايــا املقامــة ضــده مــن‬\n      ‫الســيد‪ ................. /‬الشــريك بشــركة مصنــع ‪ .........‬لتكريــر الزيــوت‬\n      ‫واملقيــدة برقــم ‪/2/426‬ق ورقــم ‪/2/427‬ق لــدى الدوائــر التجاريــة‬\n      ‫بفــرع احملكمــة اإلداريــة مبنطقــة مكــة املكرمــة وكذلــك القضيــة‬\n      ‫املقامــة ضــده مــن م‪ ..... /‬لــدى مكتــب الفصــل يف منازعــات األوراق‬\n      ‫التجاريــة للمطالبــة مببلــغ وقــدره(‪ )296.566‬مائتــن وســتة وتســعون‬\n      ‫ألــف وخمســمائة وســتة وســتون ريــال واحملــدد لنظرهــا جلســة الثالثــاء‬\n      ‫‪1431/01/04‬ه ـ وذلــك نظيــر أتعــاب مقدارهــا (‪ )100.000‬مائــة ألــف‬\n      ‫ريــال بالنســبة للقضايــا املنظــورة لــدى الدوائــر التجارية تدفــع عند توقيع‬\n      ‫العقــد وكذلــك مبلــغ وقــدره (‪ )5.000‬خمســة أالف ريــال أتعــاب نظيــر‬\n      ‫القيــام باملرافعــة واملدافعــة يف القضيــة املنظــورة لــدى مكتــب الفصل يف‬\n      ‫منازعــات األوراق التجاريــة ليصبــح اإلجمالــي مبلــغ وقــدره (‪)105.000‬‬\n      ‫مائــة وخمســة أالف ريــال دفــع منهــا الطــرف الثانــي للطــرف األول مبلــغ‬\n\n\n‫‪101‬‬\n\f‫وقــدره (‪ )65.000‬خمســة وســتون ألــف ريــال ليكــون الباقــي يف ذمتــه‬\n‫مبلــغ وقــدره (‪ )40.000‬أربعــون ألــف ريــال لــم تدفــع حتــى تاريخــه لــذا‬\n‫فقــد أتفــق الطرفــان علــى اآلتــي ‪ :‬أوالً‪ -:‬يقــوم الطــرف الثانــي بســداد‬\n‫كامــل املبلــغ وقــدرة (‪ )40.000‬أربعــون ألــف ريــال يف موعــد أقصــاه‬\n‫‪2010/03/30‬م ‪ .‬ثاني ـاً‪ -:‬يف حالــة عــدم قيــام الطــرف الثانــي بدفــع‬\n‫املبلــغ املســتحق يف املوعــد احملــدد فيحــق للطــرف األول التوقــف عــن‬\n‫القيــام بــدوره املنــوط بــه والتنحــي عــن قيامــه بواجباتــه كوكيــل‬\n‫للطــرف الثانــي وعــدم حضــور اجللســات دون أن يكــون للطــرف الثانــي‬\n‫حــق الرجــوع علــى الطــرف األول بــأي دعــوى أو مطالبــة ماليــة بســبب‬\n‫توقفــه عــن أداء عملــه‪ .‬ثالث ـاً‪ -:‬يحــق للطــرف األول مطالبــة الطــرف‬\n‫الثانــي بهــذا املبلــغ املشــار إليــه أعــاه وقــدره (‪ )40.000‬أربعــون ألــف‬\n‫ريــال ال غيــر‪ .‬رابعـاً‪ -:‬حــرر هــذا احملضــر مــن نســختني بيــد كل طــرف‬\n‫نســخه منهــا للعمــل بهــا وقــت اللــزوم‪ « .‬انتهــى كمــا ابــرز املدعــي اصالــة‬\n‫صــورة حكــم ديــوان املظالــم رقــم ‪/272‬د‪/‬جت‪ 12/‬لعــام ‪1431‬ه ـ واملبــن‬\n‫فيــه حضــور املدعــي اصالــة حــال كونــه وكيــا عــن املدعــى عليــه‬\n‫واحلكــم بإثبــات الصلــح الــذي اصطلــح عليــه الطرفــان يف حينــه ‪ .‬وعليــه‬\n‫وبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وعــدم حضــور املدعــى عليــه مــع‬\n‫تبلغــه وملــا ورد يف العقــد احملــرر بــن الطرفــن واملرصــود نصــه أعــاه‬\n‫ولكــون املدعــي قــد أجنــز مــا أوكل إليــه وذلــك ثابــت باحلكــم الصــادر‬\n‫مــن ديــوان املظالــم ولقولــه تعالــى « يأيهــا الذيــن امنــوا أوفــوا بالعقــود «‬\n‫ولقولــه صلــى اهلل عليــه وســلم « املســلمون علــى شــروطهم « ولكــون‬\n‫املدعــى عليــه ســلم جــزء مــن املبلــغ املتفــق عليــه وبقــي املبلــغ املدعــى بــه‬\n‫وقــدره أربعــون الــف ريــال لــكل مــا تقــدم حكمــت علــى املدعــى عليــه‬\n\n\n                                                                                          ‫‪102‬‬\n\f      ‫الغائــب عــن مجلــس احلكــم ‪ ...................‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ...............‬بدفــع مبلــغ أربعــون الــف ريــال لصالــح املدعــي‬\n      ‫اصالــة وبعــرض احلكــم علــى املدعــي قنــع بــه وجــرى إفهــام املدعــي‬\n      ‫بــان صــورة احلكــم ســوف تبعــث للمدعــى عليــه لتقــدمي اعتراضــه علــى‬\n      ‫احلكــم ففهــم ذلــك‪ .‬وعليــه رفعــت اجللســة الســاعة الثامنــة والنصــف‬\n      ‫صباحــا‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/3/27‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى منــا‬\n      ‫االطــاع نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ ‪ ...................‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n      ‫‪ 33173378‬وتاريــخ ‪1433/4/5‬ه ـ املتضمــن دعــوى ‪ .................‬ضــد‬\n      ‫‪ ...................‬واحملكــوم فيــه مبــادون باطنــه وبدراســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪103‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":98,"source_page_end":103,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7e740feb3c75440fe931836c38f0acbfd6fd5f61b0991abe46e98b40de6f3b3","normalized_text_hash":"76c03dd79c22c42a53c1fa9aa1061503e6b35190d1e270b835730fd13b09e086","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p98-33173378"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

